import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-advanced-l1-001', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is a PostgreSQL extension?', options: ['A file format for exporting data', 'A packaged bundle of SQL objects (functions, types, operators, etc.) that adds new functionality to PostgreSQL — installed with CREATE EXTENSION and managed as a single unit', 'A way to extend table column limits', 'A plugin for the psql client'], correctAnswer: 1, explanation: 'Extensions are PostgreSQL mechanism for packaging and distributing additional functionality. They bundle SQL objects, C shared libraries, and metadata into a versioned installable unit. Popular extensions include PostGIS, pg_stat_statements, uuid-ossp, and pgcrypto. Extensions can be updated with ALTER EXTENSION UPDATE.', codeSnippet: "-- List available extensions:\nSELECT name, default_version, comment\nFROM pg_available_extensions\nORDER BY name;\n\n-- Install an extension:\nCREATE EXTENSION IF NOT EXISTS pg_stat_statements;\n\n-- List installed extensions:\nSELECT extname, extversion\nFROM pg_extension;\n\n-- Remove an extension:\nDROP EXTENSION pg_stat_statements;", tags: ['advanced', 'extensions', 'create-extension'] },
  { id: 'pg-advanced-l1-002', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'How do you install the uuid-ossp extension?', options: ['Download it from the internet', 'Run CREATE EXTENSION "uuid-ossp" which loads the bundled extension providing UUID generation functions like uuid_generate_v4() for creating universally unique identifiers', 'Use ALTER DATABASE to enable it', 'Edit postgresql.conf to add it'], correctAnswer: 1, explanation: 'uuid-ossp is a contrib extension bundled with PostgreSQL. It provides functions for generating UUIDs (v1, v3, v4, v5). Note that PostgreSQL 13+ also provides gen_random_uuid() without needing any extension. The extension name requires double quotes due to the hyphen.', codeSnippet: "-- Install uuid-ossp:\nCREATE EXTENSION IF NOT EXISTS \"uuid-ossp\";\n\n-- Generate a random UUID (v4):\nSELECT uuid_generate_v4();\n-- Result: a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11\n\n-- Without extension (PG 13+):\nSELECT gen_random_uuid();\n\n-- Use in table definition:\nCREATE TABLE users (\n  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n  name TEXT NOT NULL\n);", tags: ['advanced', 'extensions', 'uuid', 'uuid-ossp'] },
  { id: 'pg-advanced-l1-003', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What does the pg_stat_statements extension do?', options: ['It creates financial statements', 'It tracks execution statistics of all SQL statements executed by the server, including call count, total/mean/min/max execution time, rows returned, and buffer usage — essential for query performance analysis', 'It generates table statistics', 'It provides SQL syntax checking'], correctAnswer: 1, explanation: 'pg_stat_statements is one of the most important extensions for performance tuning. It records normalized query text (with constants replaced by $N parameters), execution counts, timing, buffer hits/reads, and more. It helps identify the most time-consuming queries and those with poor buffer hit ratios.', codeSnippet: "-- Enable (requires server restart for shared_preload):\n-- postgresql.conf:\n-- shared_preload_libraries = 'pg_stat_statements'\n\nCREATE EXTENSION pg_stat_statements;\n\n-- Top 10 queries by total time:\nSELECT query,\n  calls,\n  round(total_exec_time::numeric, 2) AS total_ms,\n  round(mean_exec_time::numeric, 2) AS mean_ms,\n  rows\nFROM pg_stat_statements\nORDER BY total_exec_time DESC\nLIMIT 10;\n\n-- Reset statistics:\nSELECT pg_stat_statements_reset();", tags: ['advanced', 'extensions', 'pg-stat-statements', 'performance'] },
  { id: 'pg-advanced-l1-004', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is PL/pgSQL?', options: ['A PostgreSQL client tool', 'PostgreSQL built-in procedural language that allows writing functions and procedures with variables, control structures (IF/ELSE, loops), exception handling, and SQL integration — it extends SQL with programming logic', 'A query optimizer', 'A backup utility'], correctAnswer: 1, explanation: 'PL/pgSQL is a loadable procedural language installed by default in every PostgreSQL database. It is designed for creating functions, procedures, and triggers. It supports variables, conditionals, loops, cursors, exception handling, and direct SQL execution. It runs inside the database server for optimal performance.', codeSnippet: "-- Simple PL/pgSQL function:\nCREATE OR REPLACE FUNCTION greet(name TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN 'Hello, ' || name || '!';\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Call the function:\nSELECT greet('World');\n-- Result: Hello, World!\n\n-- Function with variable:\nCREATE OR REPLACE FUNCTION add_tax(price NUMERIC)\nRETURNS NUMERIC AS $$\nDECLARE\n  tax_rate NUMERIC := 0.2;\nBEGIN\n  RETURN price * (1 + tax_rate);\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'functions', 'procedural'] },
  { id: 'pg-advanced-l1-005', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you declare variables in a PL/pgSQL function?', options: ['Use VAR keyword', 'Variables are declared in the DECLARE block between the function header and BEGIN, specifying name, data type, and optional default value — they are local to the function execution', 'Use SET to create variables', 'Variables are declared inside BEGIN block'], correctAnswer: 1, explanation: 'The DECLARE section comes before BEGIN and defines local variables. Each variable has a name, a data type, and an optional default value or initialization expression. Variables can also reference table column types with %TYPE or entire row types with %ROWTYPE.', codeSnippet: "CREATE OR REPLACE FUNCTION calc_discount(\n  original_price NUMERIC,\n  customer_type TEXT\n) RETURNS NUMERIC AS $$\nDECLARE\n  discount_rate NUMERIC := 0;\n  final_price NUMERIC;\n  today DATE := CURRENT_DATE;\nBEGIN\n  IF customer_type = 'premium' THEN\n    discount_rate := 0.2;\n  ELSIF customer_type = 'regular' THEN\n    discount_rate := 0.1;\n  END IF;\n\n  final_price := original_price * (1 - discount_rate);\n  RETURN final_price;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT calc_discount(100, 'premium');  -- 80.00", tags: ['advanced', 'plpgsql', 'variables', 'declare'] },
  { id: 'pg-advanced-l1-006', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use IF/ELSIF/ELSE in PL/pgSQL?', options: ['Use CASE WHEN only', 'PL/pgSQL supports IF...THEN...ELSIF...THEN...ELSE...END IF syntax for conditional logic inside functions, allowing branching based on runtime conditions', 'Use WHERE clause for conditions', 'Conditional logic is not supported'], correctAnswer: 1, explanation: 'IF/ELSIF/ELSE provides standard conditional branching in PL/pgSQL. Note the spelling is ELSIF (not ELSEIF). Each branch requires THEN. The block must end with END IF (with a semicolon). You can nest IF blocks and combine conditions with AND/OR.', codeSnippet: "CREATE OR REPLACE FUNCTION get_grade(score INTEGER)\nRETURNS TEXT AS $$\nBEGIN\n  IF score >= 90 THEN\n    RETURN 'A';\n  ELSIF score >= 80 THEN\n    RETURN 'B';\n  ELSIF score >= 70 THEN\n    RETURN 'C';\n  ELSIF score >= 60 THEN\n    RETURN 'D';\n  ELSE\n    RETURN 'F';\n  END IF;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT get_grade(85);  -- B\nSELECT get_grade(42);  -- F", tags: ['advanced', 'plpgsql', 'if-else', 'control-flow'] },
  { id: 'pg-advanced-l1-007', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you return a value from a PL/pgSQL function?', options: ['Use OUTPUT keyword', 'Use the RETURN statement to return a single value matching the declared RETURNS type, or use RETURN NEXT/RETURN QUERY for set-returning functions that return multiple rows', 'Values are returned automatically', 'Use SELECT INTO to return values'], correctAnswer: 1, explanation: 'RETURN expr exits the function and returns the value. For RETURNS SETOF or RETURNS TABLE functions, use RETURN NEXT (appends a row) or RETURN QUERY (appends all rows from a query). A bare RETURN with no value exits a void function or a set-returning function (signaling end of results).', codeSnippet: "-- Return single value:\nCREATE FUNCTION square(n INTEGER)\nRETURNS INTEGER AS $$\nBEGIN\n  RETURN n * n;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Return multiple rows:\nCREATE FUNCTION get_active_users()\nRETURNS SETOF TEXT AS $$\nBEGIN\n  RETURN QUERY\n    SELECT name FROM users WHERE active = true;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Return table:\nCREATE FUNCTION user_summary()\nRETURNS TABLE(name TEXT, order_count BIGINT) AS $$\nBEGIN\n  RETURN QUERY\n    SELECT u.name, count(o.id)\n    FROM users u LEFT JOIN orders o ON u.id = o.user_id\n    GROUP BY u.name;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'return', 'set-returning'] },
  { id: 'pg-advanced-l1-008', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What does SELECT INTO do inside a PL/pgSQL function?', options: ['It creates a new table', 'Inside PL/pgSQL, SELECT INTO assigns query results to variables — it stores column values from a single row into declared variables, which is different from the SQL SELECT INTO that creates a table', 'It exports data to a file', 'It inserts data into another table'], correctAnswer: 1, explanation: 'In PL/pgSQL, SELECT INTO var1, var2 FROM ... stores the first row result into the specified variables. If the query returns no rows, the variables are set to NULL. Use the FOUND variable to check if a row was returned. This is different from the SQL command SELECT INTO which creates a new table.', codeSnippet: "CREATE OR REPLACE FUNCTION get_user_info(user_id INTEGER)\nRETURNS TEXT AS $$\nDECLARE\n  user_name TEXT;\n  user_email TEXT;\nBEGIN\n  SELECT name, email\n  INTO user_name, user_email\n  FROM users\n  WHERE id = user_id;\n\n  IF NOT FOUND THEN\n    RETURN 'User not found';\n  END IF;\n\n  RETURN user_name || ' <' || user_email || '>';\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT get_user_info(1);\n-- Result: John Doe <john@example.com>", tags: ['advanced', 'plpgsql', 'select-into', 'variables'] },
  { id: 'pg-advanced-l1-009', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'What is a trigger in PostgreSQL?', options: ['A scheduled job that runs periodically', 'A database object that automatically executes a specified function when a particular event (INSERT, UPDATE, DELETE, TRUNCATE) occurs on a table — triggers enforce business rules and maintain data integrity automatically', 'A type of index for fast lookups', 'A notification sent to clients'], correctAnswer: 1, explanation: 'Triggers are event-driven procedures attached to tables. They fire automatically before or after INSERT, UPDATE, DELETE, or TRUNCATE operations. Triggers call trigger functions written in PL/pgSQL (or other languages). They are used for auditing, validation, maintaining derived data, and enforcing complex business rules.', codeSnippet: "-- Step 1: Create the trigger function\nCREATE OR REPLACE FUNCTION update_modified_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.modified_at = NOW();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Step 2: Create the trigger\nCREATE TRIGGER set_modified_at\n  BEFORE UPDATE ON products\n  FOR EACH ROW\n  EXECUTE FUNCTION update_modified_at();\n\n-- Now any UPDATE on products automatically\n-- sets modified_at to the current timestamp", tags: ['advanced', 'triggers', 'before-trigger', 'automation'] },
  { id: 'pg-advanced-l1-010', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'What is the difference between BEFORE and AFTER triggers?', options: ['BEFORE triggers are older and deprecated', 'BEFORE triggers fire before the operation and can modify or cancel the row being inserted/updated, while AFTER triggers fire after the operation is complete and see the final state — BEFORE is used for validation/modification, AFTER for logging/side effects', 'AFTER triggers are faster', 'There is no difference'], correctAnswer: 1, explanation: 'BEFORE triggers can modify NEW values (the row being inserted/updated) and can cancel the operation by returning NULL. AFTER triggers see the committed row and cannot change it, but are ideal for logging, auditing, or cascading changes to other tables. BEFORE triggers returning NULL prevents the row operation.', codeSnippet: "-- BEFORE trigger: validate and modify data\nCREATE FUNCTION validate_email()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.email = lower(trim(NEW.email));\n  IF NEW.email !~ '^[^@]+@[^@]+$' THEN\n    RAISE EXCEPTION 'Invalid email: %', NEW.email;\n  END IF;\n  RETURN NEW;  -- must return NEW for BEFORE triggers\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER normalize_email\n  BEFORE INSERT OR UPDATE ON users\n  FOR EACH ROW EXECUTE FUNCTION validate_email();\n\n-- AFTER trigger: log changes\nCREATE FUNCTION log_changes()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO audit_log(table_name, action, row_id)\n  VALUES (TG_TABLE_NAME, TG_OP, NEW.id);\n  RETURN NULL;  -- return value ignored for AFTER\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER audit_users\n  AFTER INSERT OR UPDATE OR DELETE ON users\n  FOR EACH ROW EXECUTE FUNCTION log_changes();", tags: ['advanced', 'triggers', 'before', 'after', 'timing'] },
  { id: 'pg-advanced-l1-011', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'What is the difference between FOR EACH ROW and FOR EACH STATEMENT triggers?', options: ['FOR EACH ROW is slower', 'FOR EACH ROW triggers fire once for every affected row with access to NEW/OLD row data, while FOR EACH STATEMENT triggers fire once per SQL statement regardless of how many rows are affected — use row-level for per-row logic, statement-level for aggregate actions', 'FOR EACH STATEMENT accesses individual rows', 'They produce the same results'], correctAnswer: 1, explanation: 'FOR EACH ROW triggers execute for every row affected by the operation. An UPDATE affecting 100 rows fires the trigger 100 times. FOR EACH STATEMENT fires once regardless of affected rows. Statement-level triggers do not have access to NEW/OLD variables. They are useful for actions that should happen once per operation.', codeSnippet: "-- FOR EACH ROW: fires per affected row\nCREATE TRIGGER per_row_trigger\n  AFTER INSERT ON orders\n  FOR EACH ROW  -- fires once per inserted row\n  EXECUTE FUNCTION process_order();\n\n-- FOR EACH STATEMENT: fires once per statement\nCREATE TRIGGER per_stmt_trigger\n  AFTER INSERT ON orders\n  FOR EACH STATEMENT  -- fires once total\n  EXECUTE FUNCTION notify_batch_complete();\n\n-- INSERT INTO orders VALUES (1), (2), (3);\n-- per_row_trigger fires 3 times\n-- per_stmt_trigger fires 1 time\n\n-- Statement-level trigger function:\nCREATE FUNCTION notify_batch_complete()\nRETURNS TRIGGER AS $$\nBEGIN\n  PERFORM pg_notify('orders', 'batch inserted');\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'row-level', 'statement-level'] },
  { id: 'pg-advanced-l1-012', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a trigger that fires only on specific column updates?', options: ['Triggers always fire on all columns', 'Use the OF clause in CREATE TRIGGER to specify which columns should cause the trigger to fire — the trigger only executes when the listed columns are included in the UPDATE SET clause, reducing unnecessary trigger executions', 'Use a WHERE clause in the trigger', 'Check columns inside the trigger function'], correctAnswer: 1, explanation: 'The OF clause filters trigger execution to specific columns. CREATE TRIGGER ... BEFORE UPDATE OF price, quantity ON products fires only when price or quantity are in the SET clause. This is more efficient than checking inside the trigger function. Note: the trigger fires even if the value does not actually change.', codeSnippet: "-- Trigger only on specific columns:\nCREATE TRIGGER price_change_trigger\n  BEFORE UPDATE OF price, discount\n  ON products\n  FOR EACH ROW\n  EXECUTE FUNCTION log_price_change();\n\n-- This trigger fires:\nUPDATE products SET price = 29.99 WHERE id = 1;\n-- YES: price is in the OF list\n\nUPDATE products SET name = 'New Name' WHERE id = 1;\n-- NO: name is not in the OF list\n\nUPDATE products SET price = 29.99, name = 'X' WHERE id = 1;\n-- YES: price is in the OF list", tags: ['advanced', 'triggers', 'column-specific', 'update-trigger'] },
  { id: 'pg-advanced-l1-013', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'NOTIFY/LISTEN', question: 'What is the LISTEN/NOTIFY mechanism in PostgreSQL?', options: ['A logging system for database events', 'A built-in asynchronous notification system where sessions can LISTEN on named channels and other sessions can NOTIFY those channels with optional payload messages — useful for real-time event-driven architectures without polling', 'A way to send emails from PostgreSQL', 'A query result streaming protocol'], correctAnswer: 1, explanation: 'LISTEN/NOTIFY provides a simple pub/sub messaging system built into PostgreSQL. Clients register interest in channels with LISTEN. Any session can send notifications with NOTIFY. Notifications include the channel name and an optional text payload. This enables real-time updates without polling the database.', codeSnippet: "-- Session 1: Listen for notifications\nLISTEN new_orders;\n\n-- Session 2: Send a notification\nNOTIFY new_orders, 'Order #1234 created';\n\n-- Session 1 receives:\n-- Asynchronous notification \"new_orders\" with\n-- payload \"Order #1234 created\" received from\n-- server process with PID 12345.\n\n-- Alternative syntax:\nSELECT pg_notify('new_orders', 'Order #5678');\n\n-- Stop listening:\nUNLISTEN new_orders;\nUNLISTEN *;  -- unlisten all channels", tags: ['advanced', 'notify-listen', 'pub-sub', 'async'] },
  { id: 'pg-advanced-l1-014', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'NOTIFY/LISTEN', question: 'How do you use NOTIFY with a trigger to send real-time updates?', options: ['NOTIFY cannot be used in triggers', 'Create a trigger function that calls pg_notify() after data changes, sending the channel name and a JSON payload containing the changed data — this enables applications to receive real-time database change events', 'Use AFTER triggers with RAISE NOTICE', 'Configure postgresql.conf for notifications'], correctAnswer: 1, explanation: 'Combining triggers with pg_notify() creates a real-time change data capture pattern. The trigger fires on data changes and sends a notification with details about the change. Applications listening on the channel receive instant updates. Notifications are transactional — they are only sent when the transaction commits.', codeSnippet: "-- Trigger function that notifies on changes:\nCREATE OR REPLACE FUNCTION notify_order_change()\nRETURNS TRIGGER AS $$\nBEGIN\n  PERFORM pg_notify(\n    'order_changes',\n    json_build_object(\n      'action', TG_OP,\n      'order_id', NEW.id,\n      'status', NEW.status\n    )::text\n  );\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER order_notify\n  AFTER INSERT OR UPDATE ON orders\n  FOR EACH ROW\n  EXECUTE FUNCTION notify_order_change();\n\n-- Client listens:\nLISTEN order_changes;\n-- Receives JSON when orders change", tags: ['advanced', 'notify-listen', 'triggers', 'real-time'] },
  { id: 'pg-advanced-l1-015', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'What is a materialized view in PostgreSQL?', options: ['A view that updates in real-time', 'A database object that stores the result of a query physically on disk — unlike regular views that compute results on each access, materialized views cache the result and must be explicitly refreshed to reflect changes in the underlying data', 'A view with additional security', 'A temporary table created from a query'], correctAnswer: 1, explanation: 'Materialized views pre-compute and store query results. They trade storage space for query speed. Useful for complex aggregations, reports, and dashboards where slightly stale data is acceptable. Regular views re-execute the query each time. Materialized views must be refreshed manually or on a schedule.', codeSnippet: "-- Create a materialized view:\nCREATE MATERIALIZED VIEW monthly_sales AS\nSELECT\n  date_trunc('month', order_date) AS month,\n  product_id,\n  SUM(quantity) AS total_qty,\n  SUM(amount) AS total_amount\nFROM orders\nGROUP BY 1, 2;\n\n-- Query it (fast, reads cached data):\nSELECT * FROM monthly_sales\nWHERE month = '2024-01-01';\n\n-- Refresh to get latest data:\nREFRESH MATERIALIZED VIEW monthly_sales;\n\n-- Create index on materialized view:\nCREATE INDEX ON monthly_sales (month, product_id);", tags: ['advanced', 'materialized-views', 'caching', 'performance'] },
  { id: 'pg-advanced-l1-016', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you refresh a materialized view?', options: ['It refreshes automatically when data changes', 'Use REFRESH MATERIALIZED VIEW to recompute and replace all stored data — this locks the view during refresh; add CONCURRENTLY to allow reads during refresh (requires a unique index on the materialized view)', 'Use ALTER VIEW to refresh', 'Call UPDATE on the materialized view'], correctAnswer: 1, explanation: 'REFRESH MATERIALIZED VIEW replaces all stored data by re-executing the query. Without CONCURRENTLY, the view is locked during refresh and queries against it are blocked. With CONCURRENTLY, the old data remains readable while new data is computed, but it requires at least one unique index on the view.', codeSnippet: "-- Basic refresh (blocks reads during refresh):\nREFRESH MATERIALIZED VIEW monthly_sales;\n\n-- Concurrent refresh (allows reads, needs unique index):\nCREATE UNIQUE INDEX ON monthly_sales (month, product_id);\nREFRESH MATERIALIZED VIEW CONCURRENTLY monthly_sales;\n\n-- Check when last refreshed:\nSELECT relname,\n  last_refresh\nFROM pg_matviews\nJOIN pg_stat_user_tables ON matviewname = relname\nWHERE matviewname = 'monthly_sales';", tags: ['advanced', 'materialized-views', 'refresh', 'concurrently'] },
  { id: 'pg-advanced-l1-017', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'What is a regular view in PostgreSQL?', options: ['A saved query that stores results on disk', 'A named query definition that is re-executed every time it is referenced — views provide abstraction, simplify complex queries, and can restrict access to underlying table columns without storing any data themselves', 'A type of materialized view', 'A read-only copy of a table'], correctAnswer: 1, explanation: 'A view is essentially a stored SELECT statement. When you query a view, PostgreSQL replaces the view reference with the underlying query and executes it. Views do not store data. They simplify complex queries, provide a stable API when table structures change, and can enforce row/column-level security.', codeSnippet: "-- Create a view:\nCREATE VIEW active_employees AS\nSELECT id, name, email, department\nFROM employees\nWHERE active = true;\n\n-- Query the view (executes the underlying query):\nSELECT * FROM active_employees\nWHERE department = 'Engineering';\n\n-- Views can reference other views:\nCREATE VIEW engineering_team AS\nSELECT * FROM active_employees\nWHERE department = 'Engineering';\n\n-- Replace a view definition:\nCREATE OR REPLACE VIEW active_employees AS\nSELECT id, name, email, department, hire_date\nFROM employees\nWHERE active = true;", tags: ['advanced', 'views', 'create-view', 'abstraction'] },
  { id: 'pg-advanced-l1-018', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'Can you INSERT or UPDATE data through a view?', options: ['Views are always read-only', 'Simple views on a single table without aggregates, DISTINCT, GROUP BY, or UNION are automatically updatable — you can INSERT, UPDATE, and DELETE through them as if they were tables, and the changes apply to the underlying table', 'Only with materialized views', 'Only with the VIEW UPDATE extension'], correctAnswer: 1, explanation: 'PostgreSQL supports automatically updatable views for simple views. Requirements: single table reference, no aggregates/GROUP BY/DISTINCT/LIMIT/OFFSET/UNION, no window functions, no set-returning functions. More complex views can be made updatable using INSTEAD OF triggers or RULE system.', codeSnippet: "-- Simple updatable view:\nCREATE VIEW active_users AS\nSELECT id, name, email, active\nFROM users\nWHERE active = true;\n\n-- INSERT through the view:\nINSERT INTO active_users (name, email, active)\nVALUES ('Jane', 'jane@example.com', true);\n\n-- UPDATE through the view:\nUPDATE active_users\nSET email = 'jane.new@example.com'\nWHERE name = 'Jane';\n\n-- With CHECK OPTION:\nCREATE VIEW active_users AS\nSELECT id, name, email, active\nFROM users\nWHERE active = true\nWITH CHECK OPTION;\n-- Prevents inserting rows that don't match WHERE", tags: ['advanced', 'views', 'updatable-views', 'check-option'] },
  { id: 'pg-advanced-l1-019', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you raise an error or notice in PL/pgSQL?', options: ['Use PRINT statement', 'Use RAISE with a level (DEBUG, LOG, INFO, NOTICE, WARNING, EXCEPTION) — RAISE EXCEPTION aborts the current transaction, while RAISE NOTICE sends an informational message to the client without affecting execution', 'Use SIGNAL keyword', 'Use THROW statement'], correctAnswer: 1, explanation: 'RAISE is the PL/pgSQL mechanism for sending messages and raising errors. RAISE EXCEPTION rolls back the current transaction (or subtransaction). RAISE NOTICE/WARNING/INFO send messages to the client. Format strings use % as placeholder for arguments. RAISE can include ERRCODE for standard error codes.', codeSnippet: "CREATE FUNCTION safe_divide(a NUMERIC, b NUMERIC)\nRETURNS NUMERIC AS $$\nBEGIN\n  IF b = 0 THEN\n    RAISE EXCEPTION 'Division by zero: % / %', a, b\n      USING ERRCODE = 'division_by_zero';\n  END IF;\n\n  RAISE NOTICE 'Dividing % by %', a, b;\n  RETURN a / b;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT safe_divide(10, 0);\n-- ERROR: Division by zero: 10 / 0\n\nSELECT safe_divide(10, 3);\n-- NOTICE: Dividing 10 by 3\n-- Result: 3.333...", tags: ['advanced', 'plpgsql', 'raise', 'error-handling'] },
  { id: 'pg-advanced-l1-020', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the FOUND variable in PL/pgSQL?', options: ['It stores the number of rows found', 'FOUND is a boolean variable automatically set after certain statements — it is true if a SELECT INTO found a row, an UPDATE/INSERT/DELETE affected rows, or a FETCH retrieved a row; false otherwise — used to check if operations affected any data', 'It contains the first found row', 'It is a search function'], correctAnswer: 1, explanation: 'FOUND is implicitly declared in every PL/pgSQL function. After SELECT INTO, it is true if a row was assigned. After INSERT/UPDATE/DELETE, it is true if any rows were affected. After FETCH, it is true if a row was returned. It is the PL/pgSQL equivalent of checking @@ROWCOUNT or affected rows.', codeSnippet: "CREATE FUNCTION deactivate_user(uid INTEGER)\nRETURNS TEXT AS $$\nBEGIN\n  UPDATE users SET active = false WHERE id = uid;\n\n  IF NOT FOUND THEN\n    RETURN 'User not found';\n  END IF;\n\n  RETURN 'User deactivated';\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Also works with SELECT INTO:\nCREATE FUNCTION get_username(uid INTEGER)\nRETURNS TEXT AS $$\nDECLARE\n  uname TEXT;\nBEGIN\n  SELECT name INTO uname FROM users WHERE id = uid;\n  IF NOT FOUND THEN\n    RETURN 'Unknown';\n  END IF;\n  RETURN uname;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'found', 'row-check'] },
  { id: 'pg-advanced-l1-021', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What does the hstore extension provide?', options: ['Historical data storage', 'A key-value data type that stores sets of key/value string pairs in a single column — useful for semi-structured data, metadata, and configuration settings before JSONB was available', 'HTTP storage capabilities', 'Hash-based table storage'], correctAnswer: 1, explanation: 'hstore stores key-value pairs as a single value. While JSONB has largely replaced hstore for new development, hstore is simpler and faster for flat key-value data. It supports operators for containment, existence, and key/value extraction. It can be indexed with GIN or GiST indexes.', codeSnippet: "CREATE EXTENSION hstore;\n\n-- Create table with hstore column:\nCREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  attributes HSTORE\n);\n\n-- Insert data:\nINSERT INTO products (name, attributes) VALUES\n  ('Laptop', 'brand => Dell, ram => 16GB, ssd => 512GB'),\n  ('Phone', 'brand => Apple, storage => 256GB');\n\n-- Query by key:\nSELECT name, attributes -> 'brand' AS brand\nFROM products;\n\n-- Check if key exists:\nSELECT * FROM products\nWHERE attributes ? 'ssd';\n\n-- Check key-value containment:\nSELECT * FROM products\nWHERE attributes @> 'brand => Dell';", tags: ['advanced', 'extensions', 'hstore', 'key-value'] },
  { id: 'pg-advanced-l1-022', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'What are the special variables available inside a trigger function?', options: ['Only NEW is available', 'Trigger functions have access to NEW (new row for INSERT/UPDATE), OLD (old row for UPDATE/DELETE), TG_OP (operation type), TG_TABLE_NAME (table name), TG_WHEN (BEFORE/AFTER), and other TG_* variables describing the trigger context', 'Only TG_OP is available', 'Trigger functions have no special variables'], correctAnswer: 1, explanation: 'PL/pgSQL trigger functions have several special variables: NEW (new row data), OLD (old row data), TG_OP (INSERT/UPDATE/DELETE/TRUNCATE), TG_TABLE_NAME, TG_TABLE_SCHEMA, TG_WHEN (BEFORE/AFTER/INSTEAD OF), TG_LEVEL (ROW/STATEMENT), TG_NAME (trigger name), and TG_NARGS/TG_ARGV (trigger arguments).', codeSnippet: "CREATE OR REPLACE FUNCTION audit_trigger()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO audit_log (\n    table_name, operation,\n    old_data, new_data, changed_at\n  ) VALUES (\n    TG_TABLE_NAME,\n    TG_OP,\n    CASE WHEN TG_OP IN ('UPDATE', 'DELETE')\n      THEN row_to_json(OLD) END,\n    CASE WHEN TG_OP IN ('INSERT', 'UPDATE')\n      THEN row_to_json(NEW) END,\n    NOW()\n  );\n\n  -- Return appropriate value:\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'triggers', 'special-variables', 'tg-op'] },
  { id: 'pg-advanced-l1-023', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you create a stored procedure (not a function) in PostgreSQL?', options: ['Procedures are not supported', 'Use CREATE PROCEDURE which can commit and rollback transactions within its body (unlike functions) — procedures are called with CALL instead of SELECT and do not return values, making them suitable for complex multi-transaction operations', 'Use CREATE FUNCTION with VOID return', 'Use CREATE ROUTINE'], correctAnswer: 1, explanation: 'Stored procedures were introduced in PostgreSQL 11. Unlike functions, procedures can control transactions (COMMIT/ROLLBACK) within their body. They are invoked with CALL, not SELECT. They cannot return values directly but can use INOUT parameters. Use procedures when you need transaction control within the routine.', codeSnippet: "-- Create a procedure:\nCREATE OR REPLACE PROCEDURE transfer_funds(\n  from_acct INTEGER,\n  to_acct INTEGER,\n  amount NUMERIC\n)\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  UPDATE accounts SET balance = balance - amount\n  WHERE id = from_acct;\n\n  UPDATE accounts SET balance = balance + amount\n  WHERE id = to_acct;\n\n  -- Procedures can commit inside:\n  COMMIT;\nEND;\n$$;\n\n-- Call the procedure:\nCALL transfer_funds(1, 2, 100.00);\n\n-- Note: CALL, not SELECT", tags: ['advanced', 'plpgsql', 'procedures', 'call'] },
  { id: 'pg-advanced-l1-024', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you create an index on a materialized view?', options: ['Materialized views cannot have indexes', 'Create indexes on materialized views the same way as on tables using CREATE INDEX — this improves query performance against the materialized view and is required for REFRESH MATERIALIZED VIEW CONCURRENTLY', 'Use CREATE VIEW INDEX syntax', 'Indexes are created automatically'], correctAnswer: 1, explanation: 'Materialized views store data physically, so they support all index types (B-tree, GIN, GiST, BRIN, etc.). Creating appropriate indexes significantly improves query performance. At least one unique index is required to use REFRESH MATERIALIZED VIEW CONCURRENTLY. Indexes are rebuilt during each refresh.', codeSnippet: "-- Create materialized view:\nCREATE MATERIALIZED VIEW product_stats AS\nSELECT product_id,\n  COUNT(*) AS order_count,\n  SUM(amount) AS total_revenue\nFROM orders\nGROUP BY product_id;\n\n-- Add indexes:\nCREATE INDEX ON product_stats (product_id);\nCREATE INDEX ON product_stats (total_revenue DESC);\n\n-- Required for CONCURRENTLY refresh:\nCREATE UNIQUE INDEX ON product_stats (product_id);\n\n-- Now concurrent refresh works:\nREFRESH MATERIALIZED VIEW CONCURRENTLY product_stats;", tags: ['advanced', 'materialized-views', 'indexes', 'concurrently'] },
  { id: 'pg-advanced-l1-025', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the tablefunc extension used for?', options: ['It creates function tables', 'It provides functions like crosstab() for pivoting rows into columns (cross-tabulation), connectby() for hierarchical queries, and normal_rand() for generating random data — crosstab is most commonly used for creating pivot table reports', 'It manages table functions', 'It formats tables for display'], correctAnswer: 1, explanation: 'tablefunc is a contrib extension providing crosstab functions that transform row-based data into columnar format (pivot tables). crosstab() takes a query and returns rows with values from different categories spread across columns. This is useful for reports where you need categories as column headers.', codeSnippet: "CREATE EXTENSION tablefunc;\n\n-- Sample data: sales by quarter\n-- product | quarter | amount\n-- Widget  | Q1      | 100\n-- Widget  | Q2      | 150\n-- Gadget  | Q1      | 200\n\n-- Pivot with crosstab:\nSELECT * FROM crosstab(\n  'SELECT product, quarter, amount\n   FROM quarterly_sales\n   ORDER BY 1, 2',\n  $$VALUES ('Q1'), ('Q2'), ('Q3'), ('Q4')$$\n) AS ct(\n  product TEXT,\n  q1 NUMERIC,\n  q2 NUMERIC,\n  q3 NUMERIC,\n  q4 NUMERIC\n);\n-- Result:\n-- product | q1  | q2  | q3  | q4\n-- Widget  | 100 | 150 | ... | ...", tags: ['advanced', 'extensions', 'tablefunc', 'crosstab'] },
  { id: 'pg-advanced-l1-026', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the %TYPE attribute in PL/pgSQL?', options: ['It returns the type name as a string', 'The %TYPE attribute declares a variable with the same data type as a table column — this ensures the variable type automatically matches the column type even if the column type changes, reducing maintenance', 'It casts a variable to a type', 'It checks if a variable is a certain type'], correctAnswer: 1, explanation: '%TYPE is used in the DECLARE section to reference a column data type. For example: my_var users.email%TYPE declares my_var with the same type as the email column in the users table. This creates a dependency — if the column type changes, the variable type updates automatically on next function call.', codeSnippet: "CREATE FUNCTION get_user_email(uid INTEGER)\nRETURNS TEXT AS $$\nDECLARE\n  -- Variable matches users.email column type:\n  user_email users.email%TYPE;\n  user_name users.name%TYPE;\nBEGIN\n  SELECT email, name\n  INTO user_email, user_name\n  FROM users WHERE id = uid;\n\n  RETURN user_name || ': ' || user_email;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- %ROWTYPE for entire row:\nCREATE FUNCTION get_user(uid INTEGER)\nRETURNS users AS $$\nDECLARE\n  user_row users%ROWTYPE;\nBEGIN\n  SELECT * INTO user_row FROM users WHERE id = uid;\n  RETURN user_row;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'type-attribute', 'rowtype'] },
  { id: 'pg-advanced-l1-027', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'NOTIFY/LISTEN', question: 'Are NOTIFY messages guaranteed to be delivered?', options: ['Yes, they are stored persistently', 'NOTIFY messages are transactional and only sent when the transaction commits — they are delivered to all currently connected sessions that are LISTENing, but messages are lost if no session is listening or if sessions disconnect before receiving them', 'They are queued for offline clients', 'They retry until acknowledged'], correctAnswer: 1, explanation: 'NOTIFY is transactional: if the transaction rolls back, the notification is not sent. Messages are delivered to sessions currently connected and LISTENing at the time the transaction commits. There is no message persistence — if no one is listening, the message is discarded. The notification queue has a size limit (default 8GB).', codeSnippet: "-- Notifications are transactional:\nBEGIN;\n  INSERT INTO orders VALUES (1, 'pending');\n  NOTIFY new_orders, 'order 1';  -- not sent yet\nCOMMIT;  -- notification sent now\n\nBEGIN;\n  INSERT INTO orders VALUES (2, 'pending');\n  NOTIFY new_orders, 'order 2';  -- not sent yet\nROLLBACK;  -- notification discarded\n\n-- Multiple notifications in one transaction\n-- are coalesced if they have the same\n-- channel AND payload:\nBEGIN;\n  NOTIFY ch, 'same';  -- sent once\n  NOTIFY ch, 'same';  -- coalesced (not sent)\n  NOTIFY ch, 'different';  -- sent separately\nCOMMIT;", tags: ['advanced', 'notify-listen', 'transactional', 'delivery'] },
  { id: 'pg-advanced-l1-028', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'What is a recursive view in PostgreSQL?', options: ['A view that references itself in a loop', 'A view defined using CREATE RECURSIVE VIEW which is shorthand for a view using WITH RECURSIVE CTE — it allows querying hierarchical or graph data like organizational trees, category hierarchies, or bill of materials', 'A view that auto-refreshes', 'A view with self-referencing foreign keys'], correctAnswer: 1, explanation: 'CREATE RECURSIVE VIEW is syntactic sugar for CREATE VIEW with a WITH RECURSIVE common table expression. It simplifies defining views that traverse hierarchical data. The recursive query has an anchor (base case) and a recursive term that references the view/CTE itself, building the result level by level.', codeSnippet: "-- Recursive view for org hierarchy:\nCREATE RECURSIVE VIEW org_tree(id, name, manager_id, level) AS\n  -- Anchor: top-level managers\n  SELECT id, name, manager_id, 0\n  FROM employees\n  WHERE manager_id IS NULL\n\n  UNION ALL\n\n  -- Recursive: find reports\n  SELECT e.id, e.name, e.manager_id, t.level + 1\n  FROM employees e\n  JOIN org_tree t ON e.manager_id = t.id;\n\n-- Query the hierarchy:\nSELECT repeat('  ', level) || name AS org_chart\nFROM org_tree\nORDER BY level, name;\n\n-- Equivalent to:\n-- CREATE VIEW org_tree AS\n-- WITH RECURSIVE org_tree(...) AS (...)\n-- SELECT * FROM org_tree;", tags: ['advanced', 'views', 'recursive', 'hierarchical'] },
  { id: 'pg-advanced-l1-029', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you handle dynamic SQL in PL/pgSQL?', options: ['Dynamic SQL is not supported', 'Use EXECUTE to run SQL strings constructed at runtime — this allows building queries dynamically based on parameters, table names, or conditions; use format() or quote_ident()/quote_literal() to safely build the SQL string and prevent SQL injection', 'Use PREPARE and DEALLOCATE', 'Use eval() function'], correctAnswer: 1, explanation: 'EXECUTE runs a SQL string that can be constructed dynamically. This is needed when table/column names or SQL structure varies at runtime. Always use format() with %I (identifier) and %L (literal) or quote_ident()/quote_literal() to prevent SQL injection. EXECUTE can also use USING clause for parameterized values.', codeSnippet: "CREATE FUNCTION count_rows(table_name TEXT)\nRETURNS BIGINT AS $$\nDECLARE\n  row_count BIGINT;\nBEGIN\n  -- Safe dynamic SQL with format():\n  EXECUTE format('SELECT count(*) FROM %I', table_name)\n  INTO row_count;\n  RETURN row_count;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT count_rows('users');  -- 42\n\n-- With USING clause for parameters:\nCREATE FUNCTION find_by_column(\n  tbl TEXT, col TEXT, val TEXT\n) RETURNS SETOF RECORD AS $$\nBEGIN\n  RETURN QUERY EXECUTE\n    format('SELECT * FROM %I WHERE %I = $1', tbl, col)\n    USING val;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'dynamic-sql', 'execute'] },
  { id: 'pg-advanced-l1-030', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'How do you check what version of an extension is installed?', options: ['Use SHOW EXTENSION VERSION', 'Query the pg_extension catalog table which stores the extension name and version, or use \\dx in psql to list all installed extensions with their versions, schemas, and descriptions', 'Use SELECT version() function', 'Check postgresql.conf'], correctAnswer: 1, explanation: 'pg_extension stores metadata about installed extensions including name, version, schema, and relocation status. pg_available_extensions shows all extensions that can be installed. pg_available_extension_versions shows all available versions. In psql, \\dx provides a formatted display of installed extensions.', codeSnippet: "-- List installed extensions:\nSELECT extname, extversion, extnamespace::regnamespace\nFROM pg_extension;\n\n-- Check available vs installed:\nSELECT name, default_version, installed_version\nFROM pg_available_extensions\nWHERE installed_version IS NOT NULL\nORDER BY name;\n\n-- Update an extension:\nALTER EXTENSION pg_stat_statements UPDATE;\n-- Updates to the latest available version\n\n-- In psql:\n-- \\dx              -- list installed extensions\n-- \\dx+ ext_name    -- show extension details", tags: ['advanced', 'extensions', 'version', 'pg-extension'] },
  { id: 'pg-advanced-l1-031', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'How do you disable and re-enable a trigger?', options: ['Use DROP and CREATE again', 'Use ALTER TABLE ... DISABLE TRIGGER to temporarily turn off a trigger without dropping it, and ALTER TABLE ... ENABLE TRIGGER to turn it back on — useful for bulk data loading where trigger overhead is undesirable', 'Use SET trigger_enabled = false', 'Triggers cannot be disabled'], correctAnswer: 1, explanation: 'ALTER TABLE ... DISABLE TRIGGER name turns off a specific trigger. ALTER TABLE ... DISABLE TRIGGER ALL disables all triggers on the table. Use ENABLE to re-enable. DISABLE TRIGGER USER disables all user-defined triggers (not system triggers). This is commonly used before bulk imports for performance.', codeSnippet: "-- Disable a specific trigger:\nALTER TABLE orders DISABLE TRIGGER audit_trigger;\n\n-- Disable all triggers on a table:\nALTER TABLE orders DISABLE TRIGGER ALL;\n\n-- Disable only user triggers (keep system triggers):\nALTER TABLE orders DISABLE TRIGGER USER;\n\n-- Bulk load data without trigger overhead:\nALTER TABLE orders DISABLE TRIGGER ALL;\nCOPY orders FROM '/data/orders.csv' CSV HEADER;\nALTER TABLE orders ENABLE TRIGGER ALL;\n\n-- Re-enable specific trigger:\nALTER TABLE orders ENABLE TRIGGER audit_trigger;\n\n-- List triggers on a table:\nSELECT tgname, tgenabled\nFROM pg_trigger\nWHERE tgrelid = 'orders'::regclass\n  AND NOT tgisinternal;", tags: ['advanced', 'triggers', 'disable', 'enable', 'bulk-load'] },
  { id: 'pg-advanced-l1-032', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'What is the WITH CHECK OPTION for views?', options: ['It validates the view query syntax', 'WITH CHECK OPTION prevents INSERT and UPDATE operations through the view from creating rows that would not be visible through the view — it enforces that modified rows satisfy the view WHERE clause', 'It adds a check constraint to the view', 'It verifies view permissions'], correctAnswer: 1, explanation: 'WITH CHECK OPTION ensures data modified through the view remains visible through the view. Without it, you could INSERT a row through a view that would not match the view WHERE clause (invisible through the view but present in the base table). LOCAL checks only the current view; CASCADED checks all underlying views.', codeSnippet: "-- View without CHECK OPTION:\nCREATE VIEW active_users AS\nSELECT * FROM users WHERE active = true;\n\n-- This would succeed (but row not visible in view!):\nINSERT INTO active_users (name, active)\nVALUES ('Ghost', false);\n\n-- View with CHECK OPTION:\nCREATE OR REPLACE VIEW active_users AS\nSELECT * FROM users WHERE active = true\nWITH CHECK OPTION;\n\n-- Now this fails:\nINSERT INTO active_users (name, active)\nVALUES ('Ghost', false);\n-- ERROR: new row violates check option for view\n\n-- CASCADED (default) vs LOCAL:\nWITH LOCAL CHECK OPTION    -- checks only this view\nWITH CASCADED CHECK OPTION -- checks all parent views", tags: ['advanced', 'views', 'check-option', 'data-integrity'] },
  { id: 'pg-advanced-l1-033', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between RETURNS SETOF and RETURNS TABLE in PL/pgSQL?', options: ['They are completely different features', 'Both return multiple rows — RETURNS SETOF returns rows of an existing type (table row type or composite type), while RETURNS TABLE defines column names and types inline in the function declaration, which is more convenient for custom result sets', 'RETURNS TABLE is faster', 'RETURNS SETOF is deprecated'], correctAnswer: 1, explanation: 'RETURNS SETOF type returns rows matching an existing type (table or custom composite). RETURNS TABLE(col1 type1, col2 type2) defines the return structure inline. Both are used with RETURN NEXT or RETURN QUERY. RETURNS TABLE is syntactic sugar that is often more readable for functions returning custom column sets.', codeSnippet: "-- RETURNS SETOF (existing table type):\nCREATE FUNCTION get_all_users()\nRETURNS SETOF users AS $$\nBEGIN\n  RETURN QUERY SELECT * FROM users;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- RETURNS TABLE (custom columns):\nCREATE FUNCTION user_stats()\nRETURNS TABLE(\n  username TEXT,\n  order_count BIGINT,\n  total_spent NUMERIC\n) AS $$\nBEGIN\n  RETURN QUERY\n    SELECT u.name, count(o.id), sum(o.amount)\n    FROM users u\n    LEFT JOIN orders o ON u.id = o.user_id\n    GROUP BY u.name;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Both are called the same way:\nSELECT * FROM user_stats();", tags: ['advanced', 'plpgsql', 'returns-setof', 'returns-table'] },
  { id: 'pg-advanced-l1-034', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'How do you install the pg_trgm extension for text similarity search?', options: ['It is installed by default', 'Run CREATE EXTENSION pg_trgm which provides trigram-based functions like similarity() and operators like % for fuzzy text matching — it also enables GIN and GiST indexes to accelerate LIKE, ILIKE, and similarity searches', 'Use ALTER DATABASE ADD TRIGRAM', 'Download from pgxn.org'], correctAnswer: 1, explanation: 'pg_trgm splits text into trigrams (3-character sequences) and uses them for similarity comparison. The similarity() function returns a value between 0 and 1. The % operator returns true when similarity exceeds the pg_trgm.similarity_threshold. GIN/GiST indexes with trigram ops speed up LIKE and similarity searches.', codeSnippet: "CREATE EXTENSION pg_trgm;\n\n-- Check similarity between strings:\nSELECT similarity('hello', 'hallo');\n-- Result: 0.4\n\n-- Find similar names:\nSELECT name, similarity(name, 'Jon')\nFROM users\nWHERE name % 'Jon'  -- uses threshold (default 0.3)\nORDER BY similarity(name, 'Jon') DESC;\n\n-- Create index for fast LIKE queries:\nCREATE INDEX idx_users_name_trgm\nON users USING gin (name gin_trgm_ops);\n\n-- Now these use the index:\nSELECT * FROM users WHERE name LIKE '%john%';\nSELECT * FROM users WHERE name ILIKE '%john%';", tags: ['advanced', 'extensions', 'pg-trgm', 'fuzzy-search'] },
  { id: 'pg-advanced-l1-035', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'How do you drop a trigger in PostgreSQL?', options: ['Use DELETE TRIGGER', 'Use DROP TRIGGER trigger_name ON table_name — triggers are named per table, so you must specify which table the trigger belongs to; use IF EXISTS to avoid errors if the trigger does not exist', 'Use ALTER TABLE DROP TRIGGER', 'Use REMOVE TRIGGER'], correctAnswer: 1, explanation: 'Triggers are associated with a specific table, so DROP TRIGGER requires the table name. Trigger names must be unique per table but can be reused across different tables. Dropping a trigger does not drop the trigger function — the function can be shared by multiple triggers.', codeSnippet: "-- Drop a specific trigger:\nDROP TRIGGER audit_trigger ON orders;\n\n-- Drop if exists (no error if missing):\nDROP TRIGGER IF EXISTS audit_trigger ON orders;\n\n-- Note: the trigger function still exists:\n-- DROP FUNCTION audit_func(); -- separate step\n\n-- List triggers on a table:\nSELECT tgname, tgtype, proname AS function_name\nFROM pg_trigger t\nJOIN pg_proc p ON t.tgfoid = p.oid\nWHERE tgrelid = 'orders'::regclass\n  AND NOT tgisinternal;\n\n-- Drop trigger and its function:\nDROP TRIGGER IF EXISTS audit_trigger ON orders;\nDROP FUNCTION IF EXISTS audit_func();", tags: ['advanced', 'triggers', 'drop-trigger', 'cleanup'] },
  { id: 'pg-advanced-l1-036', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you schedule automatic materialized view refreshes?', options: ['Use AUTO REFRESH clause in CREATE', 'PostgreSQL does not have built-in auto-refresh — use pg_cron extension to schedule periodic REFRESH MATERIALIZED VIEW commands, or use application-level scheduling with cron jobs or task queues', 'Materialized views auto-refresh on data change', 'Use ALTER MATERIALIZED VIEW SET REFRESH'], correctAnswer: 1, explanation: 'Unlike some other databases, PostgreSQL materialized views do not auto-refresh. Common approaches: (1) pg_cron for in-database scheduling, (2) OS cron with psql commands, (3) Application-level scheduling, (4) Trigger-based refresh (can be expensive). Choose refresh frequency based on data freshness requirements vs. refresh cost.', codeSnippet: "-- Method 1: pg_cron extension\nCREATE EXTENSION pg_cron;\n\n-- Refresh every hour:\nSELECT cron.schedule(\n  'refresh_sales',\n  '0 * * * *',  -- every hour\n  'REFRESH MATERIALIZED VIEW CONCURRENTLY monthly_sales'\n);\n\n-- Method 2: OS cron\n-- crontab entry:\n-- 0 * * * * psql -d mydb -c 'REFRESH MATERIALIZED VIEW CONCURRENTLY monthly_sales'\n\n-- List scheduled jobs:\nSELECT * FROM cron.job;\n\n-- Remove a scheduled job:\nSELECT cron.unschedule('refresh_sales');", tags: ['advanced', 'materialized-views', 'scheduling', 'pg-cron'] },
  { id: 'pg-advanced-l1-037', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you write a function that accepts a variable number of arguments?', options: ['Use overloaded functions only', 'Use the VARIADIC keyword to accept an array of arguments — the function receives all extra arguments as an array parameter, allowing callers to pass any number of values of the specified type', 'Variable arguments are not supported', 'Use default parameter values'], correctAnswer: 1, explanation: 'VARIADIC declares the last parameter as an array that collects all remaining arguments. The caller passes individual values which are packed into the array automatically. Inside the function, access elements normally as an array. VARIADIC must be the last parameter. Call with VARIADIC keyword to pass an existing array.', codeSnippet: "-- Function with variable arguments:\nCREATE FUNCTION sum_all(VARIADIC nums INTEGER[])\nRETURNS INTEGER AS $$\nDECLARE\n  total INTEGER := 0;\n  n INTEGER;\nBEGIN\n  FOREACH n IN ARRAY nums LOOP\n    total := total + n;\n  END LOOP;\n  RETURN total;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Call with any number of arguments:\nSELECT sum_all(1, 2, 3);        -- 6\nSELECT sum_all(10, 20, 30, 40); -- 100\n\n-- Pass an existing array:\nSELECT sum_all(VARIADIC ARRAY[1, 2, 3]);  -- 6\n\n-- Or use a simpler SQL function:\nCREATE FUNCTION sum_all_v2(VARIADIC nums INTEGER[])\nRETURNS INTEGER AS $$\n  SELECT sum(n)::INTEGER FROM unnest(nums) AS n;\n$$ LANGUAGE sql;", tags: ['advanced', 'plpgsql', 'variadic', 'arguments'] },
  { id: 'pg-advanced-l1-038', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'What is a security barrier view?', options: ['A view that requires a password', 'A view created with security_barrier = true that prevents the query optimizer from pushing user-supplied filter conditions below the view WHERE clause — this prevents information leakage through carefully crafted queries on row-level security views', 'A view that encrypts data', 'A view that logs all access'], correctAnswer: 1, explanation: 'Without security_barrier, the optimizer may reorder conditions, potentially evaluating a user-supplied function before the view WHERE clause. This could leak information about filtered-out rows. Security barrier views force the view conditions to be evaluated first, at the cost of some optimization opportunities.', codeSnippet: "-- Without security barrier (potential leak):\nCREATE VIEW my_records AS\nSELECT * FROM records WHERE user_id = current_user_id();\n-- Optimizer might evaluate user function before WHERE\n\n-- With security barrier (safe):\nCREATE VIEW my_records\n  WITH (security_barrier = true) AS\nSELECT * FROM records WHERE user_id = current_user_id();\n-- View's WHERE always evaluated first\n\n-- Example of the leak:\n-- A malicious function could inspect rows:\n-- CREATE FUNCTION leak(r records) RETURNS boolean AS $$\n--   RAISE NOTICE 'saw: %', r;\n--   RETURN true;\n-- $$ LANGUAGE plpgsql COST 0.0001;  -- cheap = runs first\n-- SELECT * FROM my_records WHERE leak(my_records);\n-- Without barrier, leak() sees ALL rows", tags: ['advanced', 'views', 'security-barrier', 'rls'] },
  { id: 'pg-advanced-l1-039', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the citext extension?', options: ['A citation text format', 'The citext extension provides a case-insensitive text data type — it performs case-insensitive comparisons internally so you do not need to use lower() or ILIKE in queries, simplifying case-insensitive matching for email addresses, usernames, etc.', 'A compressed text storage', 'A text encryption extension'], correctAnswer: 1, explanation: 'citext (case-insensitive text) internally stores text as-is but compares values case-insensitively. This avoids the need for functional indexes on lower(column) or using ILIKE everywhere. It is useful for email columns, usernames, and other data where case should be ignored for equality and uniqueness.', codeSnippet: "CREATE EXTENSION citext;\n\nCREATE TABLE users (\n  id SERIAL PRIMARY KEY,\n  email CITEXT UNIQUE NOT NULL,\n  username CITEXT UNIQUE NOT NULL\n);\n\nINSERT INTO users (email, username)\nVALUES ('John@Example.COM', 'JohnDoe');\n\n-- Case-insensitive comparison automatic:\nSELECT * FROM users WHERE email = 'john@example.com';\n-- Found! No lower() or ILIKE needed\n\n-- UNIQUE constraint is also case-insensitive:\nINSERT INTO users (email, username)\nVALUES ('JOHN@EXAMPLE.COM', 'johndoe');\n-- ERROR: duplicate key value violates unique constraint", tags: ['advanced', 'extensions', 'citext', 'case-insensitive'] },
  { id: 'pg-advanced-l1-040', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'What is a WHEN clause in a trigger definition?', options: ['It replaces the trigger function', 'The WHEN clause adds a condition to the trigger that is evaluated before the trigger function runs — the trigger function only executes if the condition is true, reducing overhead for triggers that only need to fire under specific data conditions', 'It specifies when to create the trigger', 'It sets the trigger schedule'], correctAnswer: 1, explanation: 'The WHEN clause is evaluated before calling the trigger function. If the condition is false, the trigger function is not invoked at all. This is more efficient than checking conditions inside the trigger function because it avoids the function call overhead. WHEN can reference NEW and OLD in row-level triggers.', codeSnippet: "-- Only fire trigger when status actually changes:\nCREATE TRIGGER status_change\n  AFTER UPDATE ON orders\n  FOR EACH ROW\n  WHEN (OLD.status IS DISTINCT FROM NEW.status)\n  EXECUTE FUNCTION notify_status_change();\n\n-- Only fire for high-value orders:\nCREATE TRIGGER high_value_alert\n  AFTER INSERT ON orders\n  FOR EACH ROW\n  WHEN (NEW.amount > 10000)\n  EXECUTE FUNCTION alert_high_value();\n\n-- Only fire when specific column changes:\nCREATE TRIGGER price_audit\n  AFTER UPDATE OF price ON products\n  FOR EACH ROW\n  WHEN (OLD.price <> NEW.price)\n  EXECUTE FUNCTION log_price_change();", tags: ['advanced', 'triggers', 'when-clause', 'conditional'] },
  { id: 'pg-advanced-l1-041', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you perform a simple loop in PL/pgSQL?', options: ['Use WHILE with SELECT statements', 'PL/pgSQL supports several loop types: basic LOOP with EXIT WHEN, FOR i IN 1..N for counter loops, and FOREACH for iterating over arrays — all loops are terminated with END LOOP', 'Use cursors for all iteration', 'Loops are not supported in PL/pgSQL'], correctAnswer: 1, explanation: 'PL/pgSQL offers multiple loop constructs. LOOP...END LOOP is an unconditional loop requiring EXIT or RETURN to terminate. FOR i IN 1..10 provides counted iteration. FOR record IN query iterates over query results. FOREACH element IN ARRAY iterates over array elements. WHILE condition LOOP provides conditional looping.', codeSnippet: "-- Simple counted loop:\nCREATE FUNCTION factorial(n INTEGER)\nRETURNS BIGINT AS $$\nDECLARE\n  result BIGINT := 1;\nBEGIN\n  FOR i IN 1..n LOOP\n    result := result * i;\n  END LOOP;\n  RETURN result;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT factorial(5);  -- 120\n\n-- Loop with EXIT WHEN:\nCREATE FUNCTION find_first_gap()\nRETURNS INTEGER AS $$\nDECLARE\n  i INTEGER := 1;\nBEGIN\n  LOOP\n    EXIT WHEN NOT EXISTS(\n      SELECT 1 FROM items WHERE id = i\n    );\n    i := i + 1;\n  END LOOP;\n  RETURN i;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'loops', 'for-loop'] },
  { id: 'pg-advanced-l1-042', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'What happens if you query a materialized view that has never been refreshed?', options: ['It returns current data from base tables', 'A materialized view is populated with data when first created — subsequent queries return this initial data until refreshed; however, you can create an empty materialized view with WITH NO DATA and it cannot be queried until the first REFRESH', 'It returns an empty result set', 'It throws an error'], correctAnswer: 1, explanation: 'By default, CREATE MATERIALIZED VIEW executes the query and stores the result immediately. Adding WITH NO DATA creates the view structure but does not populate it — querying it returns an error ("materialized view has not been populated") until you run REFRESH MATERIALIZED VIEW.', codeSnippet: "-- Normal creation (populated immediately):\nCREATE MATERIALIZED VIEW sales_summary AS\nSELECT product_id, sum(amount)\nFROM orders GROUP BY product_id;\n-- Data is available immediately\n\n-- Create without data:\nCREATE MATERIALIZED VIEW big_report\n  WITH NO DATA AS\nSELECT /* expensive query */\n  *\nFROM very_large_table;\n\n-- Query fails:\nSELECT * FROM big_report;\n-- ERROR: materialized view \"big_report\" has not\n-- been populated\n\n-- Must refresh first:\nREFRESH MATERIALIZED VIEW big_report;\n-- Now queries work", tags: ['advanced', 'materialized-views', 'with-no-data', 'population'] },
  { id: 'pg-advanced-l1-043', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'NOTIFY/LISTEN', question: 'What is the maximum payload size for NOTIFY messages?', options: ['Unlimited', 'The maximum payload for NOTIFY is 8000 bytes — for larger data, send a reference (ID or key) in the notification and have the listener query the database for the full data', '1 MB', '256 bytes'], correctAnswer: 1, explanation: 'NOTIFY payloads are limited to about 8000 bytes (8KB minus overhead). This is sufficient for sending identifiers, JSON snippets, or short messages. For larger data, use the notification as a signal and query the database for details. The notification queue itself can hold up to 8GB of pending notifications.', codeSnippet: "-- Send a concise notification with JSON:\nSELECT pg_notify(\n  'events',\n  json_build_object(\n    'type', 'order_created',\n    'id', 12345,\n    'timestamp', now()\n  )::text\n);\n\n-- For large data, send a reference:\nSELECT pg_notify(\n  'batch_complete',\n  json_build_object(\n    'batch_id', 42,\n    'row_count', 10000\n    -- Don't include all rows in payload!\n  )::text\n);\n-- Listener then queries:\n-- SELECT * FROM batch_results WHERE batch_id = 42;\n\n-- Check queue size:\nSELECT pg_notification_queue_usage();\n-- Returns fraction of 8GB queue used (0.0 to 1.0)", tags: ['advanced', 'notify-listen', 'payload', 'limits'] },
  { id: 'pg-advanced-l1-044', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between IMMUTABLE, STABLE, and VOLATILE function volatility?', options: ['They control variable mutability', 'IMMUTABLE functions always return the same result for the same inputs (e.g., math), STABLE functions return the same result within a single query (e.g., current_timestamp), and VOLATILE functions can return different results on each call (e.g., random()) — this affects optimization and indexing', 'They set function access permissions', 'They control transaction isolation'], correctAnswer: 1, explanation: 'Function volatility tells the optimizer how aggressively it can optimize calls. IMMUTABLE: can be pre-evaluated and used in indexes. STABLE: evaluated once per query (safe for current_timestamp). VOLATILE (default): evaluated every time. Incorrect volatility marking can cause wrong results or prevent index usage.', codeSnippet: "-- IMMUTABLE: same input always gives same output\nCREATE FUNCTION double(n INTEGER)\nRETURNS INTEGER AS $$\nBEGIN RETURN n * 2; END;\n$$ LANGUAGE plpgsql IMMUTABLE;\n-- Can be used in index expressions:\nCREATE INDEX ON t (double(value));\n\n-- STABLE: consistent within a query\nCREATE FUNCTION current_user_id()\nRETURNS INTEGER AS $$\nBEGIN\n  RETURN current_setting('app.user_id')::INTEGER;\nEND;\n$$ LANGUAGE plpgsql STABLE;\n\n-- VOLATILE (default): may return different results\nCREATE FUNCTION next_sequence()\nRETURNS INTEGER AS $$\nBEGIN\n  RETURN nextval('my_seq');\nEND;\n$$ LANGUAGE plpgsql VOLATILE;", tags: ['advanced', 'plpgsql', 'volatility', 'immutable'] },
  { id: 'pg-advanced-l1-045', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the pgcrypto extension used for?', options: ['Cryptocurrency support', 'pgcrypto provides cryptographic functions including hashing (MD5, SHA), encryption (AES, Blowfish, 3DES), random data generation (gen_random_bytes), and password hashing (crypt/gen_salt with bcrypt) — used for securing sensitive data at the database level', 'Certificate management', 'Encrypted connections only'], correctAnswer: 1, explanation: 'pgcrypto extends PostgreSQL with cryptographic functions. Key features: gen_random_uuid() (PG 13+ built-in), crypt()/gen_salt() for password hashing with bcrypt/scrypt, pgp_sym_encrypt/decrypt for symmetric encryption, pgp_pub_encrypt for asymmetric encryption, and digest()/hmac() for hashing.', codeSnippet: "CREATE EXTENSION pgcrypto;\n\n-- Hash a password with bcrypt:\nINSERT INTO users (email, password_hash)\nVALUES (\n  'user@example.com',\n  crypt('my_password', gen_salt('bf', 12))  -- bcrypt, 12 rounds\n);\n\n-- Verify a password:\nSELECT (password_hash = crypt('my_password', password_hash))\n  AS password_valid\nFROM users\nWHERE email = 'user@example.com';\n\n-- Generate random bytes:\nSELECT gen_random_bytes(32);  -- 32 random bytes\n\n-- SHA-256 hash:\nSELECT digest('hello', 'sha256');", tags: ['advanced', 'extensions', 'pgcrypto', 'security'] },
  { id: 'pg-advanced-l1-046', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'How do you list all views in a PostgreSQL database?', options: ['Use SHOW VIEWS command', 'Query the pg_views system catalog or information_schema.views to see all view definitions, or use \\dv in psql for a formatted list of views in the current database', 'Use SELECT * FROM pg_tables', 'Use LIST VIEWS command'], correctAnswer: 1, explanation: 'pg_views (simpler) and information_schema.views (SQL standard) both list views. pg_views includes schemaname, viewname, viewowner, and definition. pg_matviews lists materialized views separately. In psql, \\dv lists views, \\dm lists materialized views, and \\d+ viewname shows the view definition.', codeSnippet: "-- List all views:\nSELECT schemaname, viewname, viewowner\nFROM pg_views\nWHERE schemaname NOT IN ('pg_catalog', 'information_schema')\nORDER BY viewname;\n\n-- See view definition:\nSELECT definition\nFROM pg_views\nWHERE viewname = 'active_users';\n\n-- List materialized views:\nSELECT schemaname, matviewname, ispopulated\nFROM pg_matviews;\n\n-- In psql:\n-- \\dv         -- list views\n-- \\dv+ name   -- view details\n-- \\dm         -- list materialized views", tags: ['advanced', 'views', 'catalog', 'listing'] },
  { id: 'pg-advanced-l1-047', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use the PERFORM statement in PL/pgSQL?', options: ['It measures query performance', 'PERFORM executes a query and discards the results — it is used when you want to call a function or run a query for its side effects (like sending notifications or modifying data) without needing the returned rows', 'It creates a prepared statement', 'It is an alias for EXECUTE'], correctAnswer: 1, explanation: 'In PL/pgSQL, you cannot write a bare SELECT that is not assigned to anything (syntax error). PERFORM replaces SELECT when you do not need the result. It executes the query but throws away the output. FOUND is still set. Use PERFORM for functions called for side effects, like pg_notify(), or when you only care whether rows exist.', codeSnippet: "CREATE FUNCTION process_order(order_id INTEGER)\nRETURNS VOID AS $$\nBEGIN\n  -- PERFORM discards the result:\n  PERFORM pg_notify('orders', order_id::text);\n\n  -- Can't use bare SELECT in PL/pgSQL:\n  -- SELECT pg_notify(...);  -- ERROR!\n\n  -- PERFORM with a query:\n  PERFORM 1 FROM orders WHERE id = order_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Order % not found', order_id;\n  END IF;\n\n  -- Call function for side effects:\n  PERFORM update_inventory(order_id);\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'perform', 'side-effects'] },
  { id: 'pg-advanced-l1-048', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'Can you create a trigger on a view?', options: ['No, triggers only work on tables', 'Yes, using INSTEAD OF triggers — these fire instead of the actual INSERT/UPDATE/DELETE operation on the view, allowing you to define custom logic for how the view modifications should be applied to the underlying tables', 'Yes, with regular BEFORE/AFTER triggers', 'Only on materialized views'], correctAnswer: 1, explanation: 'INSTEAD OF triggers are specifically for views. They replace the standard action (INSERT/UPDATE/DELETE) with custom logic. This makes non-updatable views (those with joins, aggregates, etc.) modifiable by defining how changes should be applied to the underlying tables. INSTEAD OF triggers must be FOR EACH ROW.', codeSnippet: "-- View joining two tables:\nCREATE VIEW user_profiles AS\nSELECT u.id, u.name, u.email, p.bio, p.avatar\nFROM users u\nLEFT JOIN profiles p ON u.id = p.user_id;\n\n-- INSTEAD OF trigger to handle inserts:\nCREATE FUNCTION handle_profile_insert()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO users (name, email)\n  VALUES (NEW.name, NEW.email)\n  RETURNING id INTO NEW.id;\n\n  INSERT INTO profiles (user_id, bio, avatar)\n  VALUES (NEW.id, NEW.bio, NEW.avatar);\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER view_insert\n  INSTEAD OF INSERT ON user_profiles\n  FOR EACH ROW\n  EXECUTE FUNCTION handle_profile_insert();\n\n-- Now you can insert through the view:\nINSERT INTO user_profiles (name, email, bio)\nVALUES ('Alice', 'alice@ex.com', 'Hello!');", tags: ['advanced', 'triggers', 'instead-of', 'views'] },
  { id: 'pg-advanced-l1-049', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'How do you create your own extension in PostgreSQL?', options: ['Write a C program only', 'Create a control file (.control) defining extension metadata, SQL script files for creating objects, and optionally a C shared library — install in the PostgreSQL share/extension directory and load with CREATE EXTENSION', 'Extensions can only be provided by PostgreSQL', 'Use CREATE EXTENSION TEMPLATE'], correctAnswer: 1, explanation: 'A minimal extension needs: (1) name.control file with metadata (comment, default_version, schema), (2) name--version.sql file with SQL commands to create objects. Optionally include C code compiled as a shared library. The control file and SQL files go in SHAREDIR/extension/. Extensions support versioning and upgrade paths.', codeSnippet: "-- my_extension.control:\n-- comment = 'My custom extension'\n-- default_version = '1.0'\n-- module_pathname = '$libdir/my_extension'\n-- relocatable = true\n\n-- my_extension--1.0.sql:\nCREATE FUNCTION my_add(a INTEGER, b INTEGER)\nRETURNS INTEGER AS $$\nBEGIN\n  RETURN a + b;\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\n-- Install files:\n-- cp my_extension.control $(pg_config --sharedir)/extension/\n-- cp my_extension--1.0.sql $(pg_config --sharedir)/extension/\n\n-- Use:\nCREATE EXTENSION my_extension;\nSELECT my_add(1, 2);  -- 3", tags: ['advanced', 'extensions', 'custom-extension', 'development'] },
  { id: 'pg-advanced-l1-050', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'What are the limitations of materialized views compared to regular tables?', options: ['They have no limitations', 'Materialized views cannot have constraints (primary key, foreign key, unique, check), cannot be targets of INSERT/UPDATE/DELETE, cannot participate in logical replication, and their data becomes stale until refreshed — they are read-only cached query results', 'They cannot have indexes', 'They are limited to 1000 rows'], correctAnswer: 1, explanation: 'Materialized views are fundamentally read-only. You can add indexes but not constraints. They do not participate in replication. They can become stale (unlike regular views which always show current data). Refresh can be expensive for large views. They do support TABLESPACE, access control (GRANT), and row-level security.', codeSnippet: "-- Cannot INSERT/UPDATE/DELETE:\nINSERT INTO my_matview VALUES (...);\n-- ERROR: cannot change materialized view\n\n-- Cannot add constraints:\nALTER TABLE my_matview ADD CONSTRAINT pk PRIMARY KEY (id);\n-- ERROR: \"my_matview\" is not a table\n\n-- CAN add indexes:\nCREATE INDEX ON my_matview (id);  -- works!\nCREATE UNIQUE INDEX ON my_matview (id);  -- works!\n\n-- CAN control access:\nGRANT SELECT ON my_matview TO readonly_role;\nREVOKE SELECT ON my_matview FROM public;\n\n-- CAN set storage parameters:\nALTER MATERIALIZED VIEW my_matview SET TABLESPACE fast_ssd;", tags: ['advanced', 'materialized-views', 'limitations', 'constraints'] },
  { id: 'pg-advanced-l1-051', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What are OUT parameters in PL/pgSQL functions?', options: ['Parameters sent to external systems', 'OUT parameters are function parameters that return values to the caller — they allow a function to return multiple values without defining a custom type; combined with IN parameters, they provide a clean way to return structured results', 'Parameters that control output format', 'Parameters excluded from the function'], correctAnswer: 1, explanation: 'OUT parameters are assigned values inside the function body and automatically returned to the caller. A function with multiple OUT parameters returns a record. IN parameters are inputs (default), OUT are outputs, INOUT serve both purposes. OUT parameters are particularly useful when you need to return multiple values.', codeSnippet: "-- Function with OUT parameters:\nCREATE FUNCTION get_user_details(\n  IN uid INTEGER,\n  OUT user_name TEXT,\n  OUT user_email TEXT,\n  OUT order_count BIGINT\n)\nAS $$\nBEGIN\n  SELECT name, email INTO user_name, user_email\n  FROM users WHERE id = uid;\n\n  SELECT count(*) INTO order_count\n  FROM orders WHERE user_id = uid;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Call and access all OUT values:\nSELECT * FROM get_user_details(1);\n-- user_name | user_email        | order_count\n-- John      | john@example.com  | 5\n\n-- Access individual values:\nSELECT (get_user_details(1)).user_name;", tags: ['advanced', 'plpgsql', 'out-parameters', 'multiple-returns'] },
  { id: 'pg-advanced-l1-052', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'How do you create a view with column aliases?', options: ['Use AS inside the view query only', 'Specify column names after the view name in CREATE VIEW view_name(col1, col2) AS SELECT ... — this renames the output columns of the view independently of the underlying query column names', 'Use ALTER VIEW RENAME COLUMN', 'Column aliases are not supported in views'], correctAnswer: 1, explanation: 'You can rename view columns either by listing names after the view name (applies to all columns in order) or by using AS aliases in the SELECT. The parenthesized list must match the number of columns returned. Column aliases in the view name take precedence over SELECT aliases.', codeSnippet: "-- Method 1: Column list after view name:\nCREATE VIEW user_list(full_name, contact_email) AS\nSELECT name, email\nFROM users;\n\nSELECT full_name, contact_email FROM user_list;\n\n-- Method 2: AS aliases in SELECT:\nCREATE VIEW user_list AS\nSELECT\n  name AS full_name,\n  email AS contact_email\nFROM users;\n\n-- Both produce the same result:\n-- full_name | contact_email\n-- John      | john@example.com\n\n-- View columns in catalog:\nSELECT column_name, data_type\nFROM information_schema.columns\nWHERE table_name = 'user_list';", tags: ['advanced', 'views', 'column-aliases', 'naming'] },
  { id: 'pg-advanced-l1-053', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'NOTIFY/LISTEN', question: 'How do you use LISTEN/NOTIFY from application code?', options: ['Use HTTP webhooks from PostgreSQL', 'Application drivers (psycopg2, node-pg, JDBC) provide APIs to LISTEN on channels and receive asynchronous notifications — the application maintains a connection and polls or uses callbacks to process incoming notifications in real-time', 'Applications cannot use LISTEN/NOTIFY', 'Use pg_dump to export notifications'], correctAnswer: 1, explanation: 'Most PostgreSQL client libraries support asynchronous notifications. Python (psycopg2/psycopg3): conn.notifies(), Node.js (node-pg): client.on("notification"), Java (JDBC): PGConnection.getNotifications(). The application must maintain a persistent connection and periodically check for notifications or use event-driven callbacks.', codeSnippet: "-- Python with psycopg2:\nimport psycopg2\nimport select\n\nconn = psycopg2.connect(dsn)\nconn.autocommit = True\ncur = conn.cursor()\ncur.execute('LISTEN new_orders;')\n\nwhile True:\n    if select.select([conn], [], [], 5) != ([], [], []):\n        conn.poll()\n        while conn.notifies:\n            notify = conn.notifies.pop(0)\n            print(f'Got: {notify.channel}: {notify.payload}')\n\n-- Node.js with pg:\nconst client = new Client()\nawait client.connect()\nawait client.query('LISTEN new_orders')\nclient.on('notification', (msg) => {\n  console.log(msg.channel, msg.payload)\n})", tags: ['advanced', 'notify-listen', 'application', 'driver'] },
  { id: 'pg-advanced-l1-054', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the SECURITY DEFINER attribute for functions?', options: ['It defines security policies', 'SECURITY DEFINER means the function executes with the permissions of the user who created it (the owner), not the user who calls it — similar to Unix setuid, this allows controlled access to data that the caller normally cannot access directly', 'It prevents function modification', 'It requires authentication to call'], correctAnswer: 1, explanation: 'By default, functions run with SECURITY INVOKER (caller permissions). SECURITY DEFINER runs with owner permissions, allowing the function to access tables the caller cannot. This is a controlled way to grant limited access. Always set search_path in SECURITY DEFINER functions to prevent schema injection attacks.', codeSnippet: "-- Function that allows limited access to sensitive data:\nCREATE OR REPLACE FUNCTION get_my_salary()\nRETURNS NUMERIC\nSECURITY DEFINER\nSET search_path = public  -- prevent schema injection\nAS $$\nBEGIN\n  RETURN (\n    SELECT salary FROM employees\n    WHERE email = current_user\n  );\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Grant execute to all users:\nGRANT EXECUTE ON FUNCTION get_my_salary() TO PUBLIC;\n\n-- Users can see their own salary\n-- but cannot SELECT from employees table directly\n\n-- SECURITY INVOKER (default):\n-- Runs with caller's permissions\n-- SECURITY DEFINER:\n-- Runs with function owner's permissions", tags: ['advanced', 'plpgsql', 'security-definer', 'permissions'] },
  { id: 'pg-advanced-l1-055', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'How do you pass arguments to a trigger function?', options: ['Use function parameters directly', 'Pass arguments in the CREATE TRIGGER statement and access them inside the function via TG_ARGV array and TG_NARGS count — this allows a single trigger function to behave differently based on the arguments provided', 'Arguments cannot be passed to triggers', 'Use SET variables before the trigger fires'], correctAnswer: 1, explanation: 'Trigger functions are declared as RETURNS TRIGGER with no parameters. Arguments are passed via CREATE TRIGGER ... EXECUTE FUNCTION func(arg1, arg2). Inside the function, TG_NARGS contains the count and TG_ARGV[0], TG_ARGV[1], etc., contain the string values. All arguments are passed as text strings.', codeSnippet: "-- Generic audit trigger function:\nCREATE FUNCTION generic_audit()\nRETURNS TRIGGER AS $$\nDECLARE\n  audit_table TEXT := TG_ARGV[0];  -- first argument\nBEGIN\n  EXECUTE format(\n    'INSERT INTO %I (operation, table_name, data, ts)\n     VALUES ($1, $2, $3, now())',\n    audit_table\n  ) USING TG_OP, TG_TABLE_NAME, row_to_json(NEW);\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Reuse with different audit tables:\nCREATE TRIGGER orders_audit\n  AFTER INSERT ON orders FOR EACH ROW\n  EXECUTE FUNCTION generic_audit('orders_audit_log');\n\nCREATE TRIGGER users_audit\n  AFTER INSERT ON users FOR EACH ROW\n  EXECUTE FUNCTION generic_audit('users_audit_log');", tags: ['advanced', 'triggers', 'arguments', 'tg-argv'] },
  { id: 'pg-advanced-l1-056', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between LANGUAGE sql and LANGUAGE plpgsql?', options: ['They are identical', 'SQL functions contain plain SQL statements and are fully inlined by the optimizer for best performance, while PL/pgSQL functions support procedural logic (variables, loops, conditionals) but cannot be inlined — use SQL for simple cases and PL/pgSQL when procedural logic is needed', 'PL/pgSQL is faster for all cases', 'SQL language functions are deprecated'], correctAnswer: 1, explanation: 'SQL functions are transparent to the optimizer and can be inlined into the calling query, potentially enabling better optimization. PL/pgSQL functions are opaque to the optimizer (optimization barrier). For simple functions (single SELECT, mathematical expressions), SQL functions are preferred. Use PL/pgSQL when you need variables, loops, or error handling.', codeSnippet: "-- SQL function (can be inlined, optimized):\nCREATE FUNCTION full_name(first TEXT, last TEXT)\nRETURNS TEXT AS $$\n  SELECT first || ' ' || last;\n$$ LANGUAGE sql IMMUTABLE;\n\n-- PL/pgSQL function (has procedural logic):\nCREATE FUNCTION full_name_v2(first TEXT, last TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  IF first IS NULL THEN\n    RETURN last;\n  ELSIF last IS NULL THEN\n    RETURN first;\n  END IF;\n  RETURN first || ' ' || last;\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE;\n\n-- SQL function in WHERE clause (inlined):\nSELECT * FROM users\nWHERE full_name(first_name, last_name) = 'John Doe';\n-- Optimizer sees: first_name || ' ' || last_name = 'John Doe'", tags: ['advanced', 'plpgsql', 'sql-language', 'inlining'] },
  { id: 'pg-advanced-l1-057', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What does the btree_gist extension provide?', options: ['A new B-tree implementation', 'It provides GiST operator classes for standard data types (int, text, timestamp, etc.), enabling exclusion constraints that combine range and equality conditions — commonly used to prevent overlapping time ranges in scheduling applications', 'Better tree visualization', 'GiST index for binary trees'], correctAnswer: 1, explanation: 'By default, GiST indexes only support certain types (geometric, full-text, etc.). btree_gist adds GiST support for standard types, enabling exclusion constraints that mix range (&&) and equality (=) operators. This is essential for preventing overlapping ranges (room bookings, employee shifts, etc.).', codeSnippet: "CREATE EXTENSION btree_gist;\n\n-- Prevent double-booking rooms:\nCREATE TABLE room_bookings (\n  id SERIAL PRIMARY KEY,\n  room_id INTEGER NOT NULL,\n  booked_during TSTZRANGE NOT NULL,\n  EXCLUDE USING GIST (\n    room_id WITH =,\n    booked_during WITH &&\n  )\n);\n\n-- This succeeds:\nINSERT INTO room_bookings (room_id, booked_during)\nVALUES (1, '[2024-01-01 09:00, 2024-01-01 10:00)');\n\n-- This fails (overlapping time for same room):\nINSERT INTO room_bookings (room_id, booked_during)\nVALUES (1, '[2024-01-01 09:30, 2024-01-01 11:00)');\n-- ERROR: conflicting key value violates\n-- exclusion constraint", tags: ['advanced', 'extensions', 'btree-gist', 'exclusion-constraint'] },
  { id: 'pg-advanced-l1-058', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'In what order do multiple triggers on the same table fire?', options: ['In the order they were created', 'Multiple triggers of the same type on the same table fire in alphabetical order by trigger name — you can control execution order by choosing trigger names strategically (e.g., prefixing with numbers like 01_validate, 02_audit)', 'In random order', 'Only one trigger can exist per table'], correctAnswer: 1, explanation: 'When multiple triggers of the same kind (same event, same timing) exist on a table, they fire in alphabetical order by name. This is the only way to control ordering. Each trigger calls its own function. A BEFORE trigger returning NULL cancels the operation and prevents subsequent triggers from firing.', codeSnippet: "-- Triggers fire in alphabetical order:\n\n-- Fires first (a_ prefix):\nCREATE TRIGGER a_validate\n  BEFORE INSERT ON orders FOR EACH ROW\n  EXECUTE FUNCTION validate_order();\n\n-- Fires second (b_ prefix):\nCREATE TRIGGER b_normalize\n  BEFORE INSERT ON orders FOR EACH ROW\n  EXECUTE FUNCTION normalize_order();\n\n-- Fires third (c_ prefix):\nCREATE TRIGGER c_audit\n  BEFORE INSERT ON orders FOR EACH ROW\n  EXECUTE FUNCTION audit_order();\n\n-- If a_validate returns NULL,\n-- b_normalize and c_audit do NOT fire\n-- and the INSERT is cancelled", tags: ['advanced', 'triggers', 'ordering', 'alphabetical'] },
  { id: 'pg-advanced-l1-059', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'How do you change a view definition without dropping it?', options: ['Views cannot be changed after creation', 'Use CREATE OR REPLACE VIEW to update the query definition — this preserves existing grants, dependencies, and column permissions; however, you cannot remove columns or change column types, only add new columns at the end', 'Use ALTER VIEW to change the query', 'Edit the view in pg_views directly'], correctAnswer: 1, explanation: 'CREATE OR REPLACE VIEW modifies the view definition while keeping permissions and dependent objects intact. Restrictions: cannot remove columns, cannot change column data types, can only add new columns at the end. To make incompatible changes, you must DROP and re-CREATE the view (and re-grant permissions).', codeSnippet: "-- Original view:\nCREATE VIEW user_list AS\nSELECT id, name, email FROM users;\n\n-- Add a column (OK):\nCREATE OR REPLACE VIEW user_list AS\nSELECT id, name, email, created_at FROM users;\n\n-- Change query logic (OK if columns compatible):\nCREATE OR REPLACE VIEW user_list AS\nSELECT id, name, email, created_at\nFROM users\nWHERE active = true;\n\n-- Remove a column (FAILS):\nCREATE OR REPLACE VIEW user_list AS\nSELECT id, name FROM users;\n-- ERROR: cannot drop columns from view\n\n-- Must DROP and re-CREATE for column removal:\nDROP VIEW user_list;\nCREATE VIEW user_list AS\nSELECT id, name FROM users;", tags: ['advanced', 'views', 'create-or-replace', 'modify'] },
  { id: 'pg-advanced-l1-060', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you iterate over query results in PL/pgSQL?', options: ['Use a cursor only', 'Use FOR record IN SELECT ... LOOP to iterate over each row of a query result — the loop variable is automatically declared as a record type and can access columns with dot notation', 'Use WHILE with FETCH', 'Query iteration is not supported'], correctAnswer: 1, explanation: 'FOR ... IN query LOOP is the most common way to iterate over query results. The loop variable is implicitly declared as RECORD type. Each iteration assigns the next row. The loop handles cursor management internally. For dynamic queries, use FOR ... IN EXECUTE string LOOP.', codeSnippet: "-- Iterate over query results:\nCREATE FUNCTION process_pending_orders()\nRETURNS INTEGER AS $$\nDECLARE\n  rec RECORD;\n  processed INTEGER := 0;\nBEGIN\n  FOR rec IN\n    SELECT id, customer_id, amount\n    FROM orders\n    WHERE status = 'pending'\n    ORDER BY created_at\n  LOOP\n    -- Access columns with dot notation:\n    RAISE NOTICE 'Processing order %: $%',\n      rec.id, rec.amount;\n\n    UPDATE orders SET status = 'processed'\n    WHERE id = rec.id;\n\n    processed := processed + 1;\n  END LOOP;\n\n  RETURN processed;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'for-loop', 'query-iteration'] },
  { id: 'pg-advanced-l1-061', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the lo (large object) extension?', options: ['A locale extension', 'The lo extension provides the lo data type and a trigger that automatically manages large object cleanup — when a row containing a large object reference is deleted or updated, the trigger automatically removes the orphaned large object from pg_largeobject', 'A logging extension', 'A locking mechanism extension'], correctAnswer: 1, explanation: 'PostgreSQL large objects (stored in pg_largeobject) are not automatically deleted when references to them are removed from user tables. The lo extension provides a lo type (alias for OID) and a trigger function lo_manage() that automatically unlinks large objects when their references are deleted or updated.', codeSnippet: "CREATE EXTENSION lo;\n\nCREATE TABLE documents (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  content LO  -- large object reference\n);\n\n-- Trigger to auto-cleanup large objects:\nCREATE TRIGGER manage_docs_lo\n  BEFORE UPDATE OR DELETE ON documents\n  FOR EACH ROW\n  EXECUTE FUNCTION lo_manage(content);\n\n-- Insert a large object:\nINSERT INTO documents (name, content)\nVALUES ('report.pdf', lo_import('/path/to/report.pdf'));\n\n-- When row is deleted, the large object is also removed:\nDELETE FROM documents WHERE id = 1;\n-- Large object automatically unlinked", tags: ['advanced', 'extensions', 'lo', 'large-objects'] },
  { id: 'pg-advanced-l1-062', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you drop a materialized view?', options: ['Use DROP VIEW', 'Use DROP MATERIALIZED VIEW view_name — materialized views are separate from regular views and require this specific command; use CASCADE to also drop dependent objects and IF EXISTS to avoid errors if it does not exist', 'Use DELETE FROM matview', 'Use TRUNCATE matview'], correctAnswer: 1, explanation: 'DROP MATERIALIZED VIEW removes the view and all its stored data and indexes. It is separate from DROP VIEW (which only works on regular views). CASCADE drops dependent objects. RESTRICT (default) prevents dropping if dependencies exist. You can also use TRUNCATE to remove data without dropping the view structure.', codeSnippet: "-- Drop a materialized view:\nDROP MATERIALIZED VIEW monthly_sales;\n\n-- Drop if exists (no error):\nDROP MATERIALIZED VIEW IF EXISTS monthly_sales;\n\n-- Drop with dependencies:\nDROP MATERIALIZED VIEW monthly_sales CASCADE;\n\n-- Just remove data (keep structure):\n-- Re-create with no data:\nREFRESH MATERIALIZED VIEW monthly_sales;\n-- There's no TRUNCATE for matviews, but you can:\nCREATE MATERIALIZED VIEW empty_view WITH NO DATA AS\nSELECT 1;  -- placeholder\n\n-- Check dependencies before dropping:\nSELECT dependent_ns.nspname, dependent_view.relname\nFROM pg_depend\nJOIN pg_class dependent_view ON pg_depend.objid = dependent_view.oid\nJOIN pg_namespace dependent_ns ON dependent_view.relnamespace = dependent_ns.oid\nWHERE refobjid = 'monthly_sales'::regclass;", tags: ['advanced', 'materialized-views', 'drop', 'cleanup'] },
  { id: 'pg-advanced-l1-063', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is a composite type and how is it used in PL/pgSQL?', options: ['A type that combines multiple databases', 'A composite type defines a structure with named fields (like a struct/record) — every table automatically creates a composite type of the same name, and you can create custom types for function parameters and return values', 'A type for complex numbers', 'A compressed data type'], correctAnswer: 1, explanation: 'Composite types are user-defined types with named fields. Every table implicitly defines a composite type. You can also create standalone composite types with CREATE TYPE. They are useful for function return types, variable declarations, and array elements. Access fields with dot notation.', codeSnippet: "-- Create a composite type:\nCREATE TYPE address AS (\n  street TEXT,\n  city TEXT,\n  state TEXT,\n  zip TEXT\n);\n\n-- Use in a table:\nCREATE TABLE contacts (\n  id SERIAL PRIMARY KEY,\n  name TEXT,\n  home_address ADDRESS,\n  work_address ADDRESS\n);\n\n-- Use in a function:\nCREATE FUNCTION make_address(\n  s TEXT, c TEXT, st TEXT, z TEXT\n) RETURNS ADDRESS AS $$\nDECLARE\n  addr ADDRESS;\nBEGIN\n  addr.street := s;\n  addr.city := c;\n  addr.state := st;\n  addr.zip := z;\n  RETURN addr;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Access fields:\nSELECT (home_address).city FROM contacts;", tags: ['advanced', 'plpgsql', 'composite-type', 'create-type'] },
  { id: 'pg-advanced-l1-064', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'What is a TRUNCATE trigger?', options: ['A trigger that truncates data', 'A trigger that fires when TRUNCATE is executed on the table — it can only be a FOR EACH STATEMENT trigger (not per-row since TRUNCATE does not process individual rows) and is useful for cascading truncations or audit logging', 'A trigger that shortens column values', 'TRUNCATE does not support triggers'], correctAnswer: 1, explanation: 'TRUNCATE triggers fire when a TRUNCATE command is executed. Since TRUNCATE removes all rows without processing them individually, only FOR EACH STATEMENT triggers are supported (not FOR EACH ROW). The trigger does not have access to NEW or OLD. It fires for both explicit TRUNCATE and CASCADE truncation.', codeSnippet: "-- TRUNCATE trigger for audit logging:\nCREATE FUNCTION log_truncate()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO audit_log (action, table_name, performed_at)\n  VALUES (\n    'TRUNCATE',\n    TG_TABLE_NAME,\n    NOW()\n  );\n  RETURN NULL;  -- return value ignored\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER on_truncate\n  AFTER TRUNCATE ON orders\n  FOR EACH STATEMENT\n  EXECUTE FUNCTION log_truncate();\n\n-- Now TRUNCATE is logged:\nTRUNCATE orders;\n-- audit_log records: TRUNCATE, orders, timestamp\n\n-- Note: FOR EACH ROW is not allowed:\n-- CREATE TRIGGER bad\n--   AFTER TRUNCATE ON orders\n--   FOR EACH ROW  -- ERROR!", tags: ['advanced', 'triggers', 'truncate', 'statement-level'] },
  { id: 'pg-advanced-l1-065', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'What is the difference between DROP VIEW and DROP VIEW CASCADE?', options: ['CASCADE drops the view faster', 'DROP VIEW fails if other objects depend on the view (default RESTRICT behavior), while DROP VIEW CASCADE also drops all dependent objects (other views, rules, etc.) that reference the dropped view — CASCADE should be used carefully to avoid unintended drops', 'CASCADE drops the underlying table', 'There is no difference'], correctAnswer: 1, explanation: 'RESTRICT (default) prevents dropping a view if anything depends on it. CASCADE drops the view and all dependent objects (views built on this view, rules, etc.). Always check dependencies before using CASCADE. Use pg_depend or information_schema to find what depends on a view before dropping it.', codeSnippet: "-- View dependency chain:\nCREATE VIEW base_view AS\nSELECT * FROM users WHERE active;\n\nCREATE VIEW derived_view AS\nSELECT * FROM base_view WHERE role = 'admin';\n\n-- This fails (derived_view depends on base_view):\nDROP VIEW base_view;\n-- ERROR: cannot drop view base_view because\n-- other objects depend on it\n\n-- This works (drops both views):\nDROP VIEW base_view CASCADE;\n-- NOTICE: drop cascades to view derived_view\n\n-- Check dependencies first:\nSELECT dependent.relname AS dependent_view\nFROM pg_depend d\nJOIN pg_class dependent ON d.objid = dependent.oid\nJOIN pg_class source ON d.refobjid = source.oid\nWHERE source.relname = 'base_view'\n  AND dependent.relkind = 'v';", tags: ['advanced', 'views', 'drop-cascade', 'dependencies'] },
  { id: 'pg-advanced-l1-066', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the intarray extension?', options: ['An internal array optimization', 'The intarray extension provides additional operators and functions for integer arrays including fast intersection (&), union (|), and index support — it offers GIN and GiST indexes that accelerate integer array containment and overlap queries', 'An integer array data type', 'An interval array extension'], correctAnswer: 1, explanation: 'intarray extends PostgreSQL integer array functionality with: operators (& for intersection, | for union, - for difference), functions (sort, uniq, idx), and GIN/GiST index support for fast array operations. It is useful for tagging systems, permission sets, and any data model using integer arrays.', codeSnippet: "CREATE EXTENSION intarray;\n\n-- Array operations:\nSELECT ARRAY[1,2,3] & ARRAY[2,3,4];  -- {2,3} intersection\nSELECT ARRAY[1,2,3] | ARRAY[2,3,4];  -- {1,2,3,4} union\nSELECT ARRAY[1,2,3] - ARRAY[2];      -- {1,3} difference\n\n-- Tagging system:\nCREATE TABLE articles (\n  id SERIAL PRIMARY KEY,\n  title TEXT,\n  tag_ids INTEGER[]\n);\n\n-- GIN index for fast array queries:\nCREATE INDEX ON articles USING gin (tag_ids gin__int_ops);\n\n-- Find articles with specific tags:\nSELECT * FROM articles WHERE tag_ids @> ARRAY[1, 5];\n-- Contains both tag 1 AND tag 5\n\nSELECT * FROM articles WHERE tag_ids && ARRAY[1, 5];\n-- Contains tag 1 OR tag 5", tags: ['advanced', 'extensions', 'intarray', 'array-operations'] },
  { id: 'pg-advanced-l1-067', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you handle NULL values in PL/pgSQL comparisons?', options: ['NULL equals NULL in PL/pgSQL', 'NULL comparisons in PL/pgSQL follow standard SQL rules where NULL = NULL is NULL (not true) — use IS NULL, IS NOT NULL, or IS DISTINCT FROM / IS NOT DISTINCT FROM for NULL-safe comparisons', 'PL/pgSQL automatically handles NULLs', 'Use ISNULL() function'], correctAnswer: 1, explanation: 'PL/pgSQL follows SQL NULL semantics: any comparison with NULL yields NULL (falsy in boolean context). This means IF x = NULL THEN never enters the THEN branch. Use IS NULL / IS NOT NULL for null checks. IS DISTINCT FROM is a null-safe inequality operator (treats NULL as a comparable value).', codeSnippet: "CREATE FUNCTION safe_compare(\n  a INTEGER, b INTEGER\n) RETURNS TEXT AS $$\nBEGIN\n  -- WRONG: this never matches when b is NULL\n  -- IF a = b THEN ...\n\n  -- CORRECT: null-safe comparison\n  IF a IS NOT DISTINCT FROM b THEN\n    RETURN 'equal (including both NULL)';\n  END IF;\n\n  -- Check for NULL:\n  IF a IS NULL THEN\n    RETURN 'a is NULL';\n  END IF;\n\n  -- COALESCE for default values:\n  RETURN 'a=' || a || ', b=' || COALESCE(b::TEXT, 'NULL');\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT safe_compare(NULL, NULL);  -- equal\nSELECT safe_compare(1, NULL);     -- a=1, b=NULL\nSELECT safe_compare(1, 1);        -- equal", tags: ['advanced', 'plpgsql', 'null-handling', 'comparison'] },
  { id: 'pg-advanced-l1-068', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'NOTIFY/LISTEN', question: 'What happens to NOTIFY messages when no one is listening?', options: ['They are queued for later delivery', 'Messages sent on a channel with no listeners are silently discarded — NOTIFY does not fail or raise an error, but the message is lost; applications should not rely on NOTIFY for guaranteed message delivery', 'They cause an error', 'They are stored in a system table'], correctAnswer: 1, explanation: 'NOTIFY is fire-and-forget. If no session is currently LISTENing on the channel, the notification is discarded. There is no message persistence, no queue for offline consumers, and no delivery guarantee. For reliable messaging, use a dedicated message queue (RabbitMQ, Redis, etc.) or a change data capture solution.', codeSnippet: "-- No listeners on 'events' channel:\nNOTIFY events, 'important data';\n-- Message silently discarded. No error.\n\n-- NOTIFY always succeeds (in terms of SQL):\nSELECT pg_notify('events', 'test');\n-- Returns void, no error regardless of listeners\n\n-- For reliable delivery, combine with a table:\nCREATE TABLE event_queue (\n  id BIGSERIAL PRIMARY KEY,\n  channel TEXT,\n  payload TEXT,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  processed BOOLEAN DEFAULT false\n);\n\n-- Insert + notify pattern:\nINSERT INTO event_queue (channel, payload)\nVALUES ('events', 'important data');\nNOTIFY events, 'new event in queue';\n-- Listener queries event_queue for details", tags: ['advanced', 'notify-listen', 'no-listener', 'reliability'] },
  { id: 'pg-advanced-l1-069', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'Can a materialized view reference another materialized view?', options: ['No, only base tables are allowed', 'Yes, materialized views can reference other materialized views, regular views, and tables — however, you must manage refresh order carefully since the parent materialized view may contain stale data when the child is refreshed', 'Only if they are in different schemas', 'Only with the CASCADE option'], correctAnswer: 1, explanation: 'Materialized views can be built on any queryable objects including other materialized views. The challenge is refresh ordering: if view B depends on materialized view A, you must refresh A before B to get consistent data. There is no built-in mechanism to enforce this — you must manage the order in your refresh schedule.', codeSnippet: "-- Base materialized view:\nCREATE MATERIALIZED VIEW daily_sales AS\nSELECT date_trunc('day', order_date) AS day,\n  sum(amount) AS total\nFROM orders GROUP BY 1;\n\n-- Materialized view on materialized view:\nCREATE MATERIALIZED VIEW weekly_sales AS\nSELECT date_trunc('week', day) AS week,\n  sum(total) AS weekly_total\nFROM daily_sales GROUP BY 1;\n\n-- Must refresh in correct order:\nREFRESH MATERIALIZED VIEW daily_sales;\nREFRESH MATERIALIZED VIEW weekly_sales;\n-- If reversed, weekly_sales uses stale daily data\n\n-- Automate with pg_cron:\nSELECT cron.schedule('refresh_chain', '0 2 * * *',\n  'REFRESH MATERIALIZED VIEW daily_sales;\n   REFRESH MATERIALIZED VIEW weekly_sales;'\n);", tags: ['advanced', 'materialized-views', 'chaining', 'refresh-order'] },
  { id: 'pg-advanced-l1-070', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is a cursor in PL/pgSQL?', options: ['A mouse pointer in pgAdmin', 'A database object that allows row-by-row processing of query results — cursors are useful for processing large result sets without loading all rows into memory at once, and can be passed between functions', 'A pointer to a table row', 'A type of database lock'], correctAnswer: 1, explanation: 'Cursors provide a way to traverse query results row by row. In PL/pgSQL, cursors can be implicit (FOR loop) or explicit (DECLARE CURSOR, OPEN, FETCH, CLOSE). Explicit cursors are useful when you need to process rows in a controlled manner, pass result sets between functions, or handle very large result sets.', codeSnippet: "-- Explicit cursor:\nCREATE FUNCTION process_large_result()\nRETURNS VOID AS $$\nDECLARE\n  cur CURSOR FOR\n    SELECT id, amount FROM orders\n    WHERE status = 'pending';\n  rec RECORD;\nBEGIN\n  OPEN cur;\n  LOOP\n    FETCH cur INTO rec;\n    EXIT WHEN NOT FOUND;\n\n    -- Process one row at a time:\n    RAISE NOTICE 'Order %: $%', rec.id, rec.amount;\n  END LOOP;\n  CLOSE cur;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Simpler: implicit cursor with FOR loop:\nCREATE FUNCTION process_v2() RETURNS VOID AS $$\nDECLARE rec RECORD;\nBEGIN\n  FOR rec IN SELECT id, amount FROM orders LOOP\n    RAISE NOTICE 'Order %: $%', rec.id, rec.amount;\n  END LOOP;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'cursors', 'fetch'] },
  { id: 'pg-advanced-l1-071', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'What is a materialized view vs a regular view performance trade-off?', options: ['Regular views are always faster', 'Regular views re-execute the query each time (always fresh, but potentially slow for complex queries), while materialized views return cached results instantly (fast reads, but data may be stale until refreshed) — choose based on freshness vs speed requirements', 'Materialized views are always faster', 'There is no performance difference'], correctAnswer: 1, explanation: 'Regular views: always current, no storage overhead, but query cost on every access. Materialized views: fast reads (pre-computed), require storage, data becomes stale. Best practices: use regular views for simple queries or when freshness is critical; use materialized views for expensive aggregations, reports, or read-heavy workloads where slight staleness is acceptable.', codeSnippet: "-- Regular view: always fresh, computed on each query\nCREATE VIEW fresh_stats AS\nSELECT category, avg(price), count(*)\nFROM products GROUP BY category;\n-- Each SELECT * FROM fresh_stats runs the aggregation\n\n-- Materialized view: cached, fast reads\nCREATE MATERIALIZED VIEW cached_stats AS\nSELECT category, avg(price), count(*)\nFROM products GROUP BY category;\n-- SELECT * FROM cached_stats reads cached data\n\n-- Compare query plans:\nEXPLAIN ANALYZE SELECT * FROM fresh_stats;\n-- Shows full aggregation cost\n\nEXPLAIN ANALYZE SELECT * FROM cached_stats;\n-- Shows simple sequential scan of cached data", tags: ['advanced', 'materialized-views', 'views', 'performance-tradeoff'] },
  { id: 'pg-advanced-l1-072', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'How do you update an extension to a newer version?', options: ['Drop and reinstall it', 'Use ALTER EXTENSION name UPDATE which runs the extension upgrade scripts to migrate from the current version to the latest available version — you can also specify a target version with UPDATE TO version', 'Extensions auto-update', 'Use CREATE EXTENSION with REPLACE'], correctAnswer: 1, explanation: 'ALTER EXTENSION name UPDATE runs the extension upgrade SQL scripts (e.g., name--1.0--2.0.sql) that migrate from the current to the target version. The extension must provide upgrade scripts for the version path. Always check release notes before upgrading as some updates may require additional steps.', codeSnippet: "-- Check current and available versions:\nSELECT name, installed_version, default_version\nFROM pg_available_extensions\nWHERE installed_version IS NOT NULL\n  AND installed_version <> default_version;\n\n-- Update to latest version:\nALTER EXTENSION postgis UPDATE;\n\n-- Update to specific version:\nALTER EXTENSION postgis UPDATE TO '3.4.0';\n\n-- Check available versions:\nSELECT version, installed, superuser, relocatable\nFROM pg_available_extension_versions\nWHERE name = 'postgis'\nORDER BY version;\n\n-- After update, verify:\nSELECT extname, extversion FROM pg_extension;", tags: ['advanced', 'extensions', 'update', 'upgrade'] },
  { id: 'pg-advanced-l1-073', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'How do you view the definition of an existing trigger?', options: ['Use SHOW TRIGGER command', 'Query pg_trigger joined with pg_proc for the trigger function, or use pg_get_triggerdef() function to get the complete CREATE TRIGGER statement, or use \\dS+ tablename in psql to see triggers on a table', 'Use DESCRIBE TRIGGER', 'Trigger definitions are not viewable'], correctAnswer: 1, explanation: 'pg_trigger stores trigger metadata. pg_get_triggerdef(trigger_oid) returns the complete CREATE TRIGGER SQL. In psql, \\dS+ table shows triggers. information_schema.triggers provides a standard SQL view. To see the trigger function source, query pg_proc.prosrc or use pg_get_functiondef().', codeSnippet: "-- Get trigger definition:\nSELECT pg_get_triggerdef(oid)\nFROM pg_trigger\nWHERE tgname = 'audit_trigger';\n\n-- List all triggers on a table:\nSELECT tgname, tgenabled,\n  pg_get_triggerdef(t.oid) AS definition\nFROM pg_trigger t\nWHERE tgrelid = 'orders'::regclass\n  AND NOT tgisinternal;\n\n-- View the trigger function source:\nSELECT prosrc\nFROM pg_proc\nWHERE proname = 'audit_trigger_func';\n\n-- Or use pg_get_functiondef:\nSELECT pg_get_functiondef(\n  'audit_trigger_func'::regproc\n);\n\n-- In psql:\n-- \\dS+ orders    -- shows triggers\n-- \\df+ func_name -- shows function source", tags: ['advanced', 'triggers', 'definition', 'introspection'] },
  { id: 'pg-advanced-l1-074', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between STRICT and non-STRICT functions?', options: ['STRICT functions have stricter type checking', 'A STRICT function automatically returns NULL if any input argument is NULL without executing the function body — this optimization avoids unnecessary computation; non-STRICT functions (default) always execute and must handle NULL arguments internally', 'STRICT functions cannot be overloaded', 'STRICT means the function is read-only'], correctAnswer: 1, explanation: 'STRICT (also called RETURNS NULL ON NULL INPUT) is an optimization. If any argument is NULL, PostgreSQL returns NULL immediately without calling the function. This is correct for most mathematical and string functions. Use CALLED ON NULL INPUT (default) when the function needs to handle NULLs specially.', codeSnippet: "-- STRICT: returns NULL if any arg is NULL\nCREATE FUNCTION multiply(a INTEGER, b INTEGER)\nRETURNS INTEGER AS $$\nBEGIN\n  RETURN a * b;  -- never called with NULL args\nEND;\n$$ LANGUAGE plpgsql STRICT;\n\nSELECT multiply(3, 4);     -- 12\nSELECT multiply(3, NULL);  -- NULL (function not called)\n\n-- Non-STRICT: handles NULLs explicitly\nCREATE FUNCTION safe_multiply(a INTEGER, b INTEGER)\nRETURNS INTEGER AS $$\nBEGIN\n  RETURN COALESCE(a, 0) * COALESCE(b, 0);\nEND;\n$$ LANGUAGE plpgsql;  -- default: CALLED ON NULL INPUT\n\nSELECT safe_multiply(3, NULL);  -- 0", tags: ['advanced', 'plpgsql', 'strict', 'null-handling'] },
  { id: 'pg-advanced-l1-075', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'NOTIFY/LISTEN', question: 'How does NOTIFY interact with transactions?', options: ['NOTIFY is sent immediately', 'NOTIFY messages are held until the transaction commits — if the transaction rolls back, the notifications are discarded; this ensures listeners only receive notifications for changes that were actually committed to the database', 'NOTIFY bypasses transactions', 'Each NOTIFY creates its own transaction'], correctAnswer: 1, explanation: 'NOTIFY is transactional. Notifications are queued and only delivered after COMMIT. On ROLLBACK, queued notifications are discarded. This prevents listeners from reacting to changes that were rolled back. Multiple identical notifications (same channel + payload) within one transaction are deduplicated to a single notification.', codeSnippet: "-- Notifications are transactional:\nBEGIN;\n  INSERT INTO orders VALUES (1, 100);\n  NOTIFY new_order, 'order 1';  -- queued\n  -- Listener has NOT received notification yet\nCOMMIT;\n  -- NOW listener receives 'order 1'\n\n-- Rolled back notifications are discarded:\nBEGIN;\n  INSERT INTO orders VALUES (2, 200);\n  NOTIFY new_order, 'order 2';  -- queued\nROLLBACK;\n  -- Notification 'order 2' is DISCARDED\n\n-- Deduplication within a transaction:\nBEGIN;\n  NOTIFY ch, 'same payload';\n  NOTIFY ch, 'same payload';  -- deduplicated\n  NOTIFY ch, 'different';\nCOMMIT;\n-- Listener receives 2 messages (not 3)", tags: ['advanced', 'notify-listen', 'transactions', 'commit'] },
  { id: 'pg-advanced-l1-076', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the fuzzystrmatch extension?', options: ['A string matching algorithm', 'The fuzzystrmatch extension provides functions for phonetic matching and string similarity including soundex(), metaphone(), dmetaphone() (double metaphone), and levenshtein() distance — useful for matching names that sound alike but are spelled differently', 'A configuration file matcher', 'A regex extension'], correctAnswer: 1, explanation: 'fuzzystrmatch provides approximate string matching tools. Soundex/Metaphone convert strings to phonetic codes (similar-sounding words get the same code). Levenshtein calculates edit distance (minimum changes to transform one string into another). Double Metaphone is the most accurate phonetic algorithm.', codeSnippet: "CREATE EXTENSION fuzzystrmatch;\n\n-- Soundex: phonetic matching\nSELECT soundex('Smith'), soundex('Smyth');\n-- S530, S530 (same code = similar sound)\n\n-- Metaphone: better phonetic matching\nSELECT metaphone('Thompson', 10), metaphone('Thomson', 10);\n-- TMPSN, TMSN\n\n-- Double Metaphone (most accurate):\nSELECT dmetaphone('Stephen'), dmetaphone('Steven');\n-- STFN, STFN (same!)\n\n-- Levenshtein distance:\nSELECT levenshtein('kitten', 'sitting');\n-- 3 (3 edits needed)\n\n-- Find similar names:\nSELECT name FROM users\nWHERE soundex(name) = soundex('Jon')\n  OR levenshtein(lower(name), 'jon') <= 2;", tags: ['advanced', 'extensions', 'fuzzystrmatch', 'phonetic'] },
  { id: 'pg-advanced-l1-077', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you create a function that runs in a specific schema?', options: ['Functions always run in the public schema', 'Create the function in a specific schema with CREATE FUNCTION schema_name.func_name() or use SET search_path in the function to control which schemas are searched during execution — SET search_path is important for SECURITY DEFINER functions', 'Use ALTER FUNCTION SET SCHEMA', 'Schema-specific functions are not possible'], correctAnswer: 1, explanation: 'Functions are created in the schema specified by the qualified name or the current search_path. The function body resolves unqualified table/function names using the search_path at execution time. For SECURITY DEFINER functions, always set search_path to prevent malicious schema manipulation.', codeSnippet: "-- Create function in specific schema:\nCREATE FUNCTION myschema.calculate_total(order_id INTEGER)\nRETURNS NUMERIC AS $$\nBEGIN\n  RETURN (SELECT sum(amount) FROM myschema.order_items\n    WHERE order_id = $1);\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Set search_path for safety:\nCREATE FUNCTION public.get_user(uid INTEGER)\nRETURNS TEXT\nSECURITY DEFINER\nSET search_path = public, pg_catalog\nAS $$\nBEGIN\n  RETURN (SELECT name FROM users WHERE id = uid);\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Move function to different schema:\nALTER FUNCTION calculate_total(INTEGER)\n  SET SCHEMA new_schema;", tags: ['advanced', 'plpgsql', 'schema', 'search-path'] },
  { id: 'pg-advanced-l1-078', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'What is a security invoker view (PG 15+)?', options: ['A view that checks passwords', 'A view with security_invoker = true that checks permissions using the querying user (invoker) rather than the view owner — this is the opposite of the default behavior where views use the owner permissions, providing tighter security control', 'A view that encrypts results', 'A view restricted to superusers'], correctAnswer: 1, explanation: 'By default, views check permissions as the view owner, which means a user can access data through a view even without direct table access. With security_invoker = true (PG 15+), the querying user permissions are checked, making the view respect the caller row-level security policies and table grants.', codeSnippet: "-- Default behavior (owner permissions):\nCREATE VIEW user_data AS\nSELECT * FROM sensitive_table;\n-- User with SELECT on view can see data\n-- even without SELECT on sensitive_table\n\n-- Security invoker view (PG 15+):\nCREATE VIEW user_data\n  WITH (security_invoker = true) AS\nSELECT * FROM sensitive_table;\n-- User needs SELECT on BOTH view AND sensitive_table\n-- RLS policies on sensitive_table are enforced\n\n-- This is important for row-level security:\n-- Without security_invoker, RLS may be bypassed\n-- through views owned by privileged users", tags: ['advanced', 'views', 'security-invoker', 'pg15'] },
  { id: 'pg-advanced-l1-079', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you use exception handling in PL/pgSQL?', options: ['Use TRY/CATCH blocks', 'Use BEGIN...EXCEPTION...END blocks where EXCEPTION catches specific error conditions (like unique_violation, division_by_zero) — the EXCEPTION block creates an implicit savepoint so only the current block is rolled back, not the entire transaction', 'Use ON ERROR GOTO', 'Exception handling is not available'], correctAnswer: 1, explanation: 'EXCEPTION blocks catch errors and allow recovery. Each BEGIN...EXCEPTION creates an implicit savepoint. When an exception occurs, work since that savepoint is rolled back, and the EXCEPTION handler executes. Use WHEN clause to catch specific errors. WHEN OTHERS catches any exception. SQLSTATE and SQLERRM provide error details.', codeSnippet: "CREATE FUNCTION safe_insert(p_email TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  INSERT INTO users (email) VALUES (p_email);\n  RETURN 'Inserted successfully';\nEXCEPTION\n  WHEN unique_violation THEN\n    RETURN 'Email already exists: ' || p_email;\n  WHEN check_violation THEN\n    RETURN 'Invalid email format';\n  WHEN OTHERS THEN\n    RETURN 'Unexpected error: ' || SQLERRM;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT safe_insert('new@example.com');\n-- 'Inserted successfully'\nSELECT safe_insert('new@example.com');\n-- 'Email already exists: new@example.com'\n\n-- Note: EXCEPTION has performance overhead\n-- (creates savepoint). Only use when needed.", tags: ['advanced', 'plpgsql', 'exception-handling', 'error-recovery'] },
  { id: 'pg-advanced-l1-080', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'How do you create a trigger that prevents deletion of certain rows?', options: ['Use a CHECK constraint', 'Create a BEFORE DELETE trigger that raises an exception or returns NULL for rows that should not be deleted — returning NULL from a BEFORE trigger cancels the operation for that row without an error, while RAISE EXCEPTION aborts the entire statement', 'Use REVOKE DELETE permission', 'Use a NOT DELETABLE column property'], correctAnswer: 1, explanation: 'A BEFORE DELETE trigger can prevent row deletion in two ways: (1) RETURN NULL silently cancels deletion of that specific row (other rows in the same DELETE are still processed), (2) RAISE EXCEPTION aborts the entire DELETE statement. Choose based on whether you want silent skip or error notification.', codeSnippet: "-- Prevent deletion of admin users:\nCREATE FUNCTION protect_admins()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF OLD.role = 'admin' THEN\n    RAISE EXCEPTION 'Cannot delete admin user: %', OLD.name;\n  END IF;\n  RETURN OLD;  -- allow deletion\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER no_delete_admins\n  BEFORE DELETE ON users\n  FOR EACH ROW\n  EXECUTE FUNCTION protect_admins();\n\n-- Soft delete alternative (silent skip):\nCREATE FUNCTION soft_delete()\nRETURNS TRIGGER AS $$\nBEGIN\n  UPDATE users SET deleted_at = now()\n  WHERE id = OLD.id;\n  RETURN NULL;  -- cancel the actual DELETE\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER soft_delete_trigger\n  BEFORE DELETE ON users\n  FOR EACH ROW\n  EXECUTE FUNCTION soft_delete();", tags: ['advanced', 'triggers', 'prevent-delete', 'soft-delete'] },
  { id: 'pg-advanced-l1-081', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the earthdistance extension?', options: ['A geography data type', 'The earthdistance extension provides functions to calculate great-circle distances between points on Earth using either the cube-based approach (approximate) or the point-based approach (latitude/longitude) — useful for proximity searches and location-based queries', 'An earthquake monitoring extension', 'A distance unit converter'], correctAnswer: 1, explanation: 'earthdistance works with the cube extension to calculate distances between geographic points. It provides earth_distance() for great-circle distance and ll_to_earth() to convert lat/lon to earth coordinates. For serious GIS work, PostGIS is more powerful, but earthdistance is simpler for basic proximity queries.', codeSnippet: "CREATE EXTENSION cube;\nCREATE EXTENSION earthdistance;\n\n-- Calculate distance between two points:\nSELECT earth_distance(\n  ll_to_earth(40.7128, -74.0060),   -- New York\n  ll_to_earth(51.5074, -0.1278)     -- London\n) / 1000 AS distance_km;\n-- Result: ~5570 km\n\n-- Find stores within 10km of a point:\nSELECT name, address\nFROM stores\nWHERE earth_distance(\n  ll_to_earth(latitude, longitude),\n  ll_to_earth(40.7128, -74.0060)\n) < 10000;  -- 10km in meters\n\n-- Create index for fast proximity search:\nCREATE INDEX ON stores\nUSING gist (ll_to_earth(latitude, longitude));", tags: ['advanced', 'extensions', 'earthdistance', 'geolocation'] },
  { id: 'pg-advanced-l1-082', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the difference between $$ and single quotes for function body quoting?', options: ['$$ is faster to parse', 'Dollar quoting ($$...$$) avoids the need to escape single quotes inside the function body — with standard single quotes, every quote in SQL/PL/pgSQL code must be doubled, making the code harder to read and maintain', 'Single quotes are deprecated', 'There is no functional difference'], correctAnswer: 1, explanation: '$$ dollar quoting is syntactically equivalent to single quotes but does not require escaping internal quotes. You can also use tagged dollar quotes ($tag$...$tag$) for nested quoting. This dramatically improves readability of function bodies containing SQL strings with quoted values.', codeSnippet: "-- With dollar quoting (clean, readable):\nCREATE FUNCTION greet(name TEXT)\nRETURNS TEXT AS $$\nBEGIN\n  RETURN 'Hello, ' || name || '!';\nEND;\n$$ LANGUAGE plpgsql;\n\n-- With single quotes (ugly, escape hell):\nCREATE FUNCTION greet(name TEXT)\nRETURNS TEXT AS '\nBEGIN\n  RETURN ''Hello, '' || name || ''!'';\nEND;\n' LANGUAGE plpgsql;\n\n-- Tagged dollar quotes for nested quoting:\nCREATE FUNCTION build_query()\nRETURNS TEXT AS $func$\nBEGIN\n  RETURN $sql$SELECT 'hello' FROM world$sql$;\nEND;\n$func$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'dollar-quoting', 'syntax'] },
  { id: 'pg-advanced-l1-083', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Views', question: 'How do you grant access to a view without granting access to the underlying tables?', options: ['This is not possible', 'Grant SELECT on the view and ensure the view owner has access to the underlying tables — by default, views execute with owner permissions, so users only need view access; the view acts as a security layer controlling what data users can see', 'Use SECURITY DEFINER on the view', 'Grant WITH GRANT OPTION on the view'], correctAnswer: 1, explanation: 'This is a primary security use case for views. The view owner (usually an admin/owner role) has table access. Users are granted SELECT on the view only. The view query runs with owner permissions, so users see the view results without needing direct table access. This provides a controlled, limited interface to the data.', codeSnippet: "-- Create view as admin:\nCREATE VIEW public_user_info AS\nSELECT id, name, city\nFROM users;  -- admin has access to users table\n\n-- Grant view access to readonly role:\nGRANT SELECT ON public_user_info TO readonly_role;\n\n-- readonly_role can query the view:\nSELECT * FROM public_user_info;  -- works!\n\n-- But cannot access the table directly:\nSELECT * FROM users;  -- permission denied!\n\n-- Even sensitive columns are hidden:\nSELECT email, password_hash FROM users;  -- denied\n-- These columns aren't in the view either", tags: ['advanced', 'views', 'security', 'access-control'] },
  { id: 'pg-advanced-l1-084', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'How do you create a function with default parameter values?', options: ['Use DEFAULT in function body', 'Specify default values in the parameter list with DEFAULT keyword — parameters with defaults must come after required parameters; callers can omit these arguments and the defaults are used automatically', 'Use COALESCE inside the function', 'Default parameters are not supported'], correctAnswer: 1, explanation: 'Default parameter values allow callers to omit arguments. Defaults must be constants or expressions evaluated at call time. Parameters with defaults must be at the end of the parameter list. Use named notation (param => value) to skip middle defaults. This makes functions more flexible and backward-compatible.', codeSnippet: "-- Function with default parameters:\nCREATE FUNCTION search_products(\n  keyword TEXT,\n  min_price NUMERIC DEFAULT 0,\n  max_price NUMERIC DEFAULT 999999,\n  limit_count INTEGER DEFAULT 10\n) RETURNS SETOF products AS $$\nBEGIN\n  RETURN QUERY\n    SELECT * FROM products\n    WHERE name ILIKE '%' || keyword || '%'\n      AND price BETWEEN min_price AND max_price\n    LIMIT limit_count;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Call with all defaults:\nSELECT * FROM search_products('laptop');\n\n-- Override some defaults:\nSELECT * FROM search_products('laptop', 500, 2000);\n\n-- Named notation to skip middle defaults:\nSELECT * FROM search_products(\n  'laptop', limit_count => 5\n);", tags: ['advanced', 'plpgsql', 'default-parameters', 'named-notation'] },
  { id: 'pg-advanced-l1-085', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Triggers', question: 'What is a transition table in triggers?', options: ['A table created by the trigger', 'Transition tables (REFERENCING clause) provide access to all affected rows as a set in AFTER statement-level triggers — OLD TABLE captures pre-change rows and NEW TABLE captures post-change rows, enabling efficient batch processing', 'A temporary table for trigger data', 'A table linking two triggers'], correctAnswer: 1, explanation: 'Transition tables (PG 10+) give AFTER statement-level triggers access to all affected rows at once, rather than processing row by row. This enables efficient batch operations like bulk auditing or aggregate calculations. OLD TABLE contains pre-change rows (UPDATE/DELETE), NEW TABLE contains post-change rows (INSERT/UPDATE).', codeSnippet: "-- Trigger with transition tables:\nCREATE FUNCTION batch_audit()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO audit_log (operation, row_count, changed_at)\n  VALUES (\n    TG_OP,\n    (SELECT count(*) FROM new_rows),  -- transition table\n    NOW()\n  );\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER batch_audit_trigger\n  AFTER INSERT ON orders\n  REFERENCING NEW TABLE AS new_rows\n  FOR EACH STATEMENT\n  EXECUTE FUNCTION batch_audit();\n\n-- For UPDATE:\nCREATE TRIGGER update_audit\n  AFTER UPDATE ON orders\n  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows\n  FOR EACH STATEMENT\n  EXECUTE FUNCTION compare_changes();", tags: ['advanced', 'triggers', 'transition-tables', 'referencing'] },
  { id: 'pg-advanced-l1-086', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Materialized Views', question: 'How do you check if a materialized view is populated?', options: ['Query the view and check for errors', 'Check the ispopulated column in pg_matviews catalog — it is true if the view has been populated with data (either at creation or via REFRESH), and false if created WITH NO DATA and not yet refreshed', 'Use SELECT count(*) on the view', 'Check pg_stat_user_tables'], correctAnswer: 1, explanation: 'pg_matviews.ispopulated indicates whether the materialized view contains data. A view created WITH NO DATA has ispopulated = false and cannot be queried. After REFRESH MATERIALIZED VIEW, ispopulated becomes true. This is useful for scripts that need to check if a refresh is needed before querying.', codeSnippet: "-- Check if materialized views are populated:\nSELECT matviewname, ispopulated\nFROM pg_matviews;\n\n-- Create unpopulated:\nCREATE MATERIALIZED VIEW deferred_view\n  WITH NO DATA AS\nSELECT * FROM large_table;\n\n-- Check:\nSELECT ispopulated FROM pg_matviews\nWHERE matviewname = 'deferred_view';\n-- false\n\n-- Query fails:\nSELECT * FROM deferred_view;\n-- ERROR: materialized view \"deferred_view\"\n-- has not been populated\n\n-- Refresh:\nREFRESH MATERIALIZED VIEW deferred_view;\n\n-- Now populated:\nSELECT ispopulated FROM pg_matviews\nWHERE matviewname = 'deferred_view';\n-- true", tags: ['advanced', 'materialized-views', 'ispopulated', 'status'] },
  { id: 'pg-advanced-l1-087', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'PL/pgSQL', question: 'What is the GET DIAGNOSTICS statement in PL/pgSQL?', options: ['It runs database diagnostics', 'GET DIAGNOSTICS retrieves information about the most recently executed SQL statement — it can fetch ROW_COUNT (number of affected rows), PG_CONTEXT (call stack), and RESULT_OID, providing programmatic access to statement execution details', 'It checks database health', 'It displays query plans'], correctAnswer: 1, explanation: 'GET DIAGNOSTICS captures execution metadata. ROW_COUNT gives the number of rows affected by the last SQL command (equivalent to checking @@ROWCOUNT). PG_CONTEXT provides the call stack for debugging. Use GET STACKED DIAGNOSTICS in exception handlers to get error details like RETURNED_SQLSTATE and MESSAGE_TEXT.', codeSnippet: "CREATE FUNCTION update_prices(pct NUMERIC)\nRETURNS TEXT AS $$\nDECLARE\n  affected INTEGER;\nBEGIN\n  UPDATE products SET price = price * (1 + pct/100);\n\n  GET DIAGNOSTICS affected = ROW_COUNT;\n  RETURN 'Updated ' || affected || ' products';\nEND;\n$$ LANGUAGE plpgsql;\n\n-- In exception handler:\nCREATE FUNCTION safe_op() RETURNS TEXT AS $$\nDECLARE\n  err_state TEXT;\n  err_msg TEXT;\nBEGIN\n  -- some operation...\n  RETURN 'ok';\nEXCEPTION WHEN OTHERS THEN\n  GET STACKED DIAGNOSTICS\n    err_state = RETURNED_SQLSTATE,\n    err_msg = MESSAGE_TEXT;\n  RETURN 'Error ' || err_state || ': ' || err_msg;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['advanced', 'plpgsql', 'get-diagnostics', 'row-count'] },
  { id: 'pg-advanced-l1-088', language: 'postgresql', level: 'level1', category: 'Advanced', subcategory: 'Extensions', question: 'What is the pg_visibility extension used for?', options: ['It controls view permissions', 'pg_visibility provides functions to examine the visibility map and free space map of tables — useful for diagnosing vacuum issues, understanding HOT update effectiveness, and checking whether index-only scans can be used for specific pages', 'It manages view definitions', 'It hides columns from users'], correctAnswer: 1, explanation: 'The visibility map tracks which table pages contain only tuples visible to all transactions (all-visible). Pages marked all-visible can be skipped by VACUUM and support index-only scans. pg_visibility lets you inspect this map to diagnose performance issues and verify vacuum effectiveness.', codeSnippet: "CREATE EXTENSION pg_visibility;\n\n-- Check visibility map summary:\nSELECT * FROM pg_visibility_map_summary('my_table');\n-- all_visible: pages visible to all\n-- all_frozen: pages with frozen tuples\n\n-- Check specific page:\nSELECT * FROM pg_visibility_map('my_table', 0);\n-- Returns: all_visible, all_frozen for page 0\n\n-- Percentage of all-visible pages:\nSELECT\n  all_visible::float / NULLIF(total, 0) * 100\n    AS vis_pct\nFROM (\n  SELECT\n    (pg_visibility_map_summary('my_table')).all_visible,\n    pg_relation_size('my_table') / 8192 AS total\n) s;\n-- High percentage = good for index-only scans", tags: ['advanced', 'extensions', 'pg-visibility', 'vacuum'] },
];

